import { unlock } from '@utils/lock-unlock';
import { privateApis as routerPrivateApis } from '@wordpress/router';
const { useHistory } = unlock( routerPrivateApis );

const { PrivateListView } = unlock( blockEditorPrivateApis );

const NavigationContext = createContext( {} );

// Cached BlockPreview component that doesn't rerender unnecessarily
const CachedBlockPreview = memo( function CachedBlockPreview( {
	templateId,
	blocks,
} ) {
	// Create a cache key based on template ID and blocks content
	const cacheKey = `preview-${ templateId }-${
		blocks ? JSON.stringify( blocks ) : 'null'
	}`;
	// Check if we already have a cached preview for this exact content
	if ( blockPreviewCache.has( cacheKey ) ) {
		return blockPreviewCache.get( cacheKey );
	}

	// Create new BlockPreview and cache it
	const preview = (
		<BlockPreview
			blocks={ blocks }
			additionalStyles={ [
				{
					css: `
						.wp-block {
							min-height: 0 !important;
						}
					`,
				},
			] }
		/>
	);

	blockPreviewCache.set( cacheKey, preview );
	return preview;
} );

const PageTemplate = memo( function PageTemplate( {
	template,
	page,
	isFrontPage,
} ) {
	const history = useHistory();
	const { close } = useDispatch( commandsStore );
	const { setMosaicEnabled } = useDispatch( aiStore );

	// Always call the hook, but use cached value when available
	const [ freshBlocks ] = useEntityBlockEditor( 'postType', 'wp_template', {
		id: template.id,
	} );

	// Use cached blocks if available, otherwise cache fresh blocks
	const cacheKey = `blocks-${ template.id }`;
	let blocks;

	if ( blocksCache.has( cacheKey ) ) {
		blocks = blocksCache.get( cacheKey );
	} else if ( freshBlocks ) {
		blocks = freshBlocks;
		blocksCache.set( cacheKey, freshBlocks );
	} else {
		blocks = freshBlocks; // Will be null/undefined initially
	}

	const handleClose = () => {
		document.body.classList.remove( 'big-sky__pages-modal-open' );
		setMosaicEnabled( false );
		history.navigate( `/${ page.type }/${ page.id }?canvas=edit` );
		close();
	};

	return (
		<div>
			<p>{ isFrontPage ? 'Home' : page.title.rendered }</p>
			<div
				role="button"
				tabIndex={ 0 }
				onClick={ handleClose }
				onKeyDown={ ( e ) => {
					if ( e.key === 'Enter' ) {
						handleClose();
					}
				} }
				style={ {
					cursor: 'pointer',
					opacity: page.status === 'publish' ? 1 : 0.5,
				} }
			>
				<CachedBlockPreview
					templateId={ template.id }
					blocks={ blocks }
				/>
			</div>
		</div>
	);
} );

// Create a global template cache to prevent refetching
const templateCache = new Map();
const blocksCache = new Map();
// Create a global BlockPreview cache to prevent rerenders
const blockPreviewCache = new Map();

const PagePreview = memo( function PagePreview( {
	page,
	templateSlug,
	siteMetadata,
	isFrontPage,
} ) {
	// Use cached template data if available
	const template = useSelect(
		( select ) => {
			const cacheKey = `template-${ templateSlug }`;
			if ( templateCache.has( cacheKey ) ) {
				return templateCache.get( cacheKey );
			}

			const templates = select( coreStore ).getEntityRecords(
				'postType',
				'wp_template',
				{
					per_page: -1,
				}
			);
			const foundTemplate = templates?.find(
				( t ) => t.slug === templateSlug
			);

			if ( foundTemplate ) {
				templateCache.set( cacheKey, foundTemplate );
			}

			return foundTemplate;
		},
		[ templateSlug ]
	);

	const context = useMemo(
		() => ( {
			postType: page.type,
			postId: page.id,
		} ),
		[ page.type, page.id ]
	);

	if ( ! template ) {
		return null;
	}

	return (
		<EntityProvider kind="postType" type={ page.type } id={ page.id }>
			<BlockContextProvider value={ context }>
				<PageTemplate
					template={ template }
					page={ page }
					siteMetadata={ siteMetadata }
					isFrontPage={ isFrontPage }
				/>
			</BlockContextProvider>
		</EntityProvider>
	);
} );

// Modal content that maintains both tab contents to prevent rerenders
const ModalContent = memo( function ModalContent( {
	siteMetadata,
	siteSettings,
	publishedPages,
	draftPages,
	activeTab,
} ) {
	// Combine all pages into a single list with tab markers
	const allPagesWithTabs = useMemo( () => {
		const published = ( publishedPages || [] ).map( ( page ) => ( {
			...page,
			_tab: 'pages',
		} ) );
		const drafts = ( draftPages || [] ).map( ( page ) => ( {
			...page,
			_tab: 'drafts',
		} ) );
		return [ ...published, ...drafts ];
	}, [ publishedPages, draftPages ] );

	return (
		<div className="big-sky__modal-content">
			<Masonry
				breakpointCols={ 3 }
				className="big-sky__mosaic"
				columnClassName="big-sky__mosaic__column"
			>
				{ allPagesWithTabs.map( ( page ) => {
					const isVisible = page._tab === activeTab;
					return (
						<div
							key={ page.id }
							style={ {
								opacity: isVisible ? 1 : 0,
								pointerEvents: isVisible ? 'auto' : 'none',
								position: isVisible ? 'static' : 'absolute',
								left: isVisible ? 'auto' : '-9999px',
								top: isVisible ? 'auto' : '-9999px',
								width: isVisible ? 'auto' : '1px',
								height: isVisible ? 'auto' : '1px',
								overflow: 'hidden',
							} }
						>
							<PagePreview
								page={ page }
								siteMetadata={ siteMetadata }
								isFrontPage={
									page.id === siteSettings?.page_on_front
								}
								templateSlug={
									page.template !== ''
										? page.template
										: 'page'
								}
							/>
						</div>
					);
				} ) }
			</Masonry>
		</div>
	);
} );

function AdditionalBlockContent( { block } ) {
	const { siteMetadata, siteSettings, page } = useSelect(
		( select ) => {
			const { getEntityRecord } = select( coreStore );
			return {
				siteMetadata: select( aiStore ).getSiteMetadata(),
				siteSettings: getEntityRecord( 'root', 'site' ),
				page: getEntityRecord(
					'postType',
					'page',
					block.attributes.id
				),
			};
		},
		[ block.attributes.id ]
	);
	// Use context to avoid multiple useEntityBlockEditor instances.
	const navigationBlocks = useContext( NavigationContext );
	const { editEntityRecord, saveEditedEntityRecord } =
		useDispatch( coreStore );
	if ( block.name !== 'core/navigation-link' ) {
		return null;
	}
	if ( ! page || ! siteMetadata?.navigationId ) {
		return null;
	}
	const isFrontPage = page.id === siteSettings?.page_on_front;
	const navigationId = siteMetadata.navigationId;

	// Toggle should reflect page status: ON for published, OFF for draft
	const isPublished = page.status === 'publish';

	// Hide toggle for front page instead of disabling it
	if ( isFrontPage ) {
		return null;
	}

	return (
		<ToggleControl
			__nextHasNoMarginBottom
			checked={ isPublished }
			onChange={ async () => {
				let _blocks = [ ...navigationBlocks ];

				if ( isPublished ) {
					// Page is published, so toggle OFF means draft it and remove from nav
					_blocks = _blocks.filter(
						( _block ) =>
							_block.name === 'core/navigation-link' &&
							_block.attributes.id !== page.id
					);
					await editEntityRecord( 'postType', page.type, page.id, {
						status: 'draft',
					} );
				} else {
					// Page is draft, so toggle ON means publish it and add to nav
					if (
						! _blocks.find(
							( _block ) =>
								_block.name === 'core/navigation-link' &&
								_block.attributes.id === page.id
						)
					) {
						_blocks.push(
							createBlock( 'core/navigation-link', {
								label: page.title.rendered,
								type: 'page',
								id: page.id,
								url: page.link,
								kind: 'post-type',
							} )
						);
					}
					await editEntityRecord( 'postType', page.type, page.id, {
						status: 'publish',
					} );
				}

				await saveEditedEntityRecord( 'postType', page.type, page.id );
				await editEntityRecord(
					'postType',
					'wp_navigation',
					navigationId,
					{
						blocks: _blocks,
						content: ( entity ) => serialize( entity.blocks ?? [] ),
					}
				);
			} }
		/>
	);
}

function PagesComponent( { siteMetadata, instanceId } ) {
	const [ activeTab, setActiveTab ] = useState( 'pages' );
	const tabListRef = useRef( null );
	const { close } = useDispatch( commandsStore );
	const { setMosaicEnabled } = useDispatch( aiStore );

	// Remember if block list panel was open before mosaic opened
	const wasListViewOpenRef = useRef( false );

	// Update tab indicator when active tab changes or on initial render
	useEffect( () => {
		if ( ! tabListRef.current ) return;

		// Use a small timeout to ensure DOM is ready
		const timeout = setTimeout( () => {
			const activeTabElement = tabListRef.current?.querySelector(
				`[aria-selected="true"]`
			);

			if ( activeTabElement ) {
				const tabListRect = tabListRef.current.getBoundingClientRect();
				const activeTabRect = activeTabElement.getBoundingClientRect();

				// Calculate position relative to tab list container
				const left = activeTabRect.left - tabListRect.left;
				const width = activeTabRect.width;

				// Set CSS variables for indicator positioning
				tabListRef.current.style.setProperty(
					'--selected-left',
					`${ left }px`
				);
				tabListRef.current.style.setProperty(
					'--selected-width',
					`${ width }px`
				);
			}
		}, 0 );

		return () => clearTimeout( timeout );
	}, [ activeTab ] );

	const siteSettings = useSelect(
		( select ) => select( coreStore ).getEntityRecord( 'root', 'site' ),
		[]
	);
	const allPages = useSelect(
		( select ) =>
			select( coreStore ).getEntityRecords( 'postType', 'page', {
				per_page: -1,
				status: 'draft,publish',
				orderby: 'date',
				order: 'asc',
			} ),
		[]
	);

	// Check if list view panel is currently open
	const isListViewOpen = useSelect( ( select ) => {
		// Post/Page editor (classic post editor UI)
		// eslint-disable-next-line @wordpress/data-no-store-string-literals
		const editPost = select( 'core/edit-post' );
		if ( editPost && typeof editPost.isListViewOpened === 'function' ) {
			return !! editPost.isListViewOpened();
		}

		// Site editor (Full Site Editing / block themes)
		// eslint-disable-next-line @wordpress/data-no-store-string-literals
		const editSite = select( 'core/edit-site' );
		if ( editSite ) {
			// Different Gutenberg versions expose one of these:
			if ( typeof editSite.isListViewOpened === 'function' ) {
				return !! editSite.isListViewOpened();
			}
			if ( typeof editSite.isListViewOpen === 'function' ) {
				return !! editSite.isListViewOpen();
			}
			// Some older builds had an experimental name:
			if (
				typeof editSite.__experimentalIsListViewOpened === 'function'
			) {
				return !! editSite.__experimentalIsListViewOpened();
			}
		}

		// Fallback to edit-post panel check
		if ( editPost && typeof editPost.isEditorPanelOpened === 'function' ) {
			return !! editPost.isEditorPanelOpened( 'list-view' );
		}

		return false;
	}, [] );

	const { enableComplementaryArea, disableComplementaryArea } =
		useDispatch( interfaceStore );
	// eslint-disable-next-line @wordpress/data-no-store-string-literals
	const editPostDispatch = useDispatch( 'core/edit-post' );
	const toggleEditorPanelOpened = editPostDispatch?.toggleEditorPanelOpened;
	const { editEntityRecord } = useDispatch( coreStore );

	// Store list view state and close it when mosaic opens (only on mount)
	useEffect( () => {
		// Check DOM-based detection since API might not work with default preferences
		const listViewElement = document.querySelector(
			'.editor-list-view-sidebar'
		);
		const isDOMVisible =
			listViewElement && listViewElement.offsetParent !== null;

		// Store if list view was actually open (use DOM detection as truth)
		const actuallyOpen = isListViewOpen || isDOMVisible;
		wasListViewOpenRef.current = actuallyOpen;

		let hideTimeout;

		// Close list view if it was open to prevent layout conflicts
		if ( actuallyOpen ) {
			// Try API method first
			if ( isListViewOpen && toggleEditorPanelOpened ) {
				toggleEditorPanelOpened( 'list-view' );
			}

			// Force hide with CSS if still visible
			hideTimeout = setTimeout( () => {
				const stillVisible = document.querySelector(
					'.editor-list-view-sidebar'
				);
				if ( stillVisible && stillVisible.offsetParent !== null ) {
					stillVisible.style.display = 'none';
					stillVisible.setAttribute( 'data-big-sky-hidden', 'true' );
				}
			}, 100 );
		}

		// Open pages sidebar
		enableComplementaryArea( 'core', 'big-sky/pages-sidebar' );

		// Cleanup function - restore list view if it was originally open
		return () => {
			// Clear timeout if component unmounts
			if ( hideTimeout ) {
				clearTimeout( hideTimeout );
			}

			disableComplementaryArea( 'core', 'big-sky/pages-sidebar' );

			// Restore list view if it was open before mosaic opened
			if ( wasListViewOpenRef.current && toggleEditorPanelOpened ) {
				// Try API method first
				toggleEditorPanelOpened( 'list-view' );

				// Force show with CSS if hidden by us
				const hiddenElement = document.querySelector(
					'.editor-list-view-sidebar[data-big-sky-hidden="true"]'
				);
				if ( hiddenElement ) {
					hiddenElement.style.display = '';
					hiddenElement.removeAttribute( 'data-big-sky-hidden' );
				}
			}
		};
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [
		enableComplementaryArea,
		disableComplementaryArea,
		toggleEditorPanelOpened,
	] );

	const [ navigationBlocks = [] ] = useEntityBlockEditor(
		'postType',
		'wp_navigation',
		{
			id: siteMetadata?.navigationId,
		}
	);

	// Filter pages by status for tabs
	const publishedPages = useMemo( () => {
		if ( ! allPages?.length ) {
			return [];
		}
		return allPages.filter( ( page ) => page.status === 'publish' );
	}, [ allPages ] );

	const draftPages = useMemo( () => {
		if ( ! allPages?.length ) {
			return [];
		}
		return allPages.filter( ( page ) => page.status === 'draft' );
	}, [ allPages ] );

	// Convert pages to navigation-link blocks for the block editor
	const publishedBlocks = useMemo( () => {
		return publishedPages.map( ( page ) => {
			return createBlock( 'core/navigation-link', {
				label: page.title.rendered,
				type: 'page',
				id: page.id,
				url: page.link,
				kind: 'post-type',
			} );
		} );
	}, [ publishedPages ] );

	const draftBlocks = useMemo( () => {
		return draftPages.map( ( page ) => {
			return createBlock( 'core/navigation-link', {
				label: page.title.rendered,
				type: 'page',
				id: page.id,
				url: page.link,
				kind: 'post-type',
			} );
		} );
	}, [ draftPages ] );

	const wrappedPublishedBlocks = useMemo( () => {
		return [
			createBlock(
				'core/navigation',
				{ ref: siteMetadata?.navigationId, maxNestingLevel: 5 },
				publishedBlocks
			),
		];
	}, [ publishedBlocks, siteMetadata?.navigationId ] );

	const wrappedDraftBlocks = useMemo( () => {
		return [ createBlock( 'core/navigation', {}, draftBlocks ) ];
	}, [ draftBlocks ] );

	const [ reorderKey, setReorderKey ] = useState( 0 );

	// Clear caches when content changes to ensure fresh data
	useEffect( () => {
		templateCache.clear();
		blocksCache.clear();
		blockPreviewCache.clear();
	}, [ reorderKey ] );

	async function onChange( [ navigationBlock ] ) {
		if ( ! siteMetadata?.navigationId ) {
			return;
		}
		await editEntityRecord(
			'postType',
			'wp_navigation',
			siteMetadata.navigationId,
			{
				blocks: [ ...navigationBlock.innerBlocks ],
				content: ( entity ) => serialize( entity.blocks ?? [] ),
			}
		);
		setReorderKey( ( key ) => key + 1 );
	}

	if ( ! allPages?.length ) {
		return null;
	}

	return (
		<>
			<Fill name="__unstable-block-tools-after">
				<ModalContent
					siteMetadata={ siteMetadata }
					siteSettings={ siteSettings }
					publishedPages={ publishedPages }
					draftPages={ draftPages }
					activeTab={ activeTab }
				/>
			</Fill>
			<PluginSidebar
				identifier="big-sky/pages-sidebar"
				title={ __( 'Pages', 'big-sky' ) }
			>
				<NavigationContext.Provider value={ navigationBlocks }>
					<div className="block-editor-tabbed-sidebar__tablist-and-close-button">
						<button
							type="button"
							className="components-button block-editor-tabbed-sidebar__close-button is-compact has-icon"
							aria-label={ __( 'Close Pages', 'big-sky' ) }
							onClick={ () => {
								document.body.classList.remove(
									'big-sky__pages-modal-open'
								);
								setMosaicEnabled( false );
								close();
							} }
						>
							<svg
								xmlns="http://www.w3.org/2000/svg"
								viewBox="0 0 24 24"
								width="24"
								height="24"
								aria-hidden="true"
								focusable="false"
							>
								<path d="M12 13.06l3.712 3.713 1.061-1.06L13.061 12l3.712-3.712-1.06-1.06L12 10.938 8.288 7.227l-1.061 1.06L10.939 12l-3.712 3.712 1.06 1.061L12 13.061z"></path>
							</svg>
						</button>
						<div
							role="tablist"
							aria-orientation="horizontal"
							className="block-editor-tabbed-sidebar__tablist"
							ref={ tabListRef }
						>
							<button
								id={ `pages-tab-${ instanceId }` }
								role="tab"
								aria-selected={ activeTab === 'pages' }
								aria-controls={ `pages-tabpanel-${ instanceId }` }
								className="block-editor-tabbed-sidebar__tab"
								onClick={ () => setActiveTab( 'pages' ) }
								type="button"
							>
								<span>{ __( 'Pages', 'big-sky' ) }</span>
							</button>
							<button
								id={ `drafts-tab-${ instanceId }` }
								role="tab"
								aria-selected={ activeTab === 'drafts' }
								aria-controls={ `drafts-tabpanel-${ instanceId }` }
								className="block-editor-tabbed-sidebar__tab"
								onClick={ () => setActiveTab( 'drafts' ) }
								type="button"
							>
								<span>{ __( 'Drafts', 'big-sky' ) }</span>
							</button>
						</div>
					</div>

					{ activeTab === 'pages' && (
						<div
							id={ `pages-tabpanel-${ instanceId }` }
							role="tabpanel"
							aria-labelledby={ `pages-tab-${ instanceId }` }
							className="block-editor-tabbed-sidebar__tab-content"
							style={ {
								pointerEvents: siteMetadata?.navigationId
									? 'auto'
									: 'none',
							} }
						>
							<BlockEditorProvider
								value={ wrappedPublishedBlocks }
								{ ...( siteMetadata?.navigationId && {
									onChange,
								} ) }
							>
								<BlockListSettings
									rootClientId={
										wrappedPublishedBlocks?.[ 0 ]?.clientId
									}
								/>
								<PrivateListView
									rootClientId={
										wrappedPublishedBlocks?.[ 0 ]?.clientId
									}
									additionalBlockContent={
										AdditionalBlockContent
									}
									showBlockMovers={ false }
									onSelect={ null }
									blockSettingsMenu={ null }
									isExpanded={ true }
								/>
							</BlockEditorProvider>
						</div>
					) }

					{ activeTab === 'drafts' && (
						<div
							id={ `drafts-tabpanel-${ instanceId }` }
							role="tabpanel"
							aria-labelledby={ `drafts-tab-${ instanceId }` }
							className="block-editor-tabbed-sidebar__tab-content big-sky__pages-sidebar__draft-pages"
						>
							<BlockEditorProvider value={ wrappedDraftBlocks }>
								<PrivateListView
									rootClientId={
										wrappedDraftBlocks?.[ 0 ]?.clientId
									}
									additionalBlockContent={
										AdditionalBlockContent
									}
									showBlockMovers={ false }
									onSelect={ null }
									blockSettingsMenu={ null }
								/>
							</BlockEditorProvider>
						</div>
					) }
				</NavigationContext.Provider>
			</PluginSidebar>
		</>
	);
}

const Pages = withInstanceId( PagesComponent );

function BlockListSettings( { rootClientId } ) {
	const { updateBlockListSettings } = useDispatch( blockEditorStore );
	useEffect( () => {
		updateBlockListSettings( rootClientId, {
			allowedBlocks: [ 'core/navigation-link' ],
		} );
	}, [ updateBlockListSettings, rootClientId ] );
	return null;
}

export function Mosaic( { siteMetadata } ) {
	const isOpen = useSelect(
		( select ) => select( commandsStore ).isOpen(),
		[]
	);

	return isOpen === true && <Pages siteMetadata={ siteMetadata } />;
}
