import useCurrentScreen from '@hooks/use-current-screen';
import useCanvas from '@hooks/use-canvas.js';
import { useSelect } from '@wordpress/data';
import { store as editorStore } from '@wordpress/editor';
import useShowSiteSpec from '@hooks/use-show-site-spec';

const allowedPostTypes = [ 'page', 'post' ];

/**
 * Hook to determine if Big Sky should be loaded.
 * Returns true when editing pages or posts in the appropriate editor modes
 * and the site has been onboarded.
 * @return {boolean} Whether Big Sky should be loaded.
 */
export default function useShouldLoadBigSky() {
	const { postType, isPostEditor, isSiteEditor } = useCurrentScreen();
	const { canvasMode } = useCanvas();
	const editorMode = useSelect( ( select ) =>
		select( editorStore ).getEditorMode()
	);
	const showSiteSpec = useShowSiteSpec();

	return (
		( isSiteEditor && canvasMode === 'edit' ) ||
		( isPostEditor &&
			editorMode === 'visual' &&
			allowedPostTypes.includes( postType ) &&
			! showSiteSpec )
	);
}
