/**
 * Internal dependencies
 */
import log from '@utils/log-debug.js';

/*
 * Logs the agent's thoughts from the update object for debugging purposes.
 *
 * @param {Object} update - The update object containing status and message parts.
 */
export default function logDebugThought( update ) {
	const messageParts = update?.status?.message?.parts || [];

	if ( messageParts.length === 0 ) {
		return;
	}

	// Find a part with toolId 'think'.
	const thoughtPart = messageParts.find(
		( part ) =>
			part.data?.toolId === 'think' ||
			part.data?.toolId === 'wpcom__think' // wpcom__think is the ability version of think tool.
	);
	const thoughts = thoughtPart?.data?.arguments?.thoughts;
	if ( thoughts ) {
		log.info(
			'Agent Thought: %c%s\n',
			`font-style: italic; color: gray;`,
			thoughts
		);
	}
}
