/**
 * WordPress dependencies
 */
import { useDispatch, useSelect } from '@wordpress/data';
import { useEffect, useRef } from '@wordpress/element';
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import { recordTracksEvent } from '@utils/tracks';
import useBlueprintCopyMask from '@hooks/use-blueprint-copy-mask';

/**
 * Editor-URL flag Calypso sets when it hands a freshly built blueprint site
 * over after spec confirm, asking us to open the copy walkthrough rather than
 * waiting for the customer to work out that they should say something first.
 */
export const BLUEPRINT_WALKTHROUGH_PARAM = 'blueprint-walkthrough';

/**
 * The opening message, sent on the customer's behalf but never shown to them.
 *
 * Deliberately just a greeting. The agent already knows to offer the walkthrough
 * on the first turn of a blueprint site, and a greeting lets it make that offer
 * in its own words and wait for a real yes. Asking for the rewrite outright
 * reads as consent already given, so the agent skips the offer and starts
 * editing the page before the customer has said anything at all.
 */
const KICKOFF_MESSAGE = __( 'Hello', 'big-sky' );

/**
 * Headless hook that opens the blueprint copy walkthrough on arrival.
 *
 * Blueprint sites land in the editor with the theme's demo copy still in place
 * and an agent already primed to personalize it, but nothing happens until
 * someone speaks first — so the customer has to guess that typing "hi" is the
 * way in. Calypso adds this flag to the editor URL when it hands off after spec
 * confirm; opening the conversation for them is the whole point of the hand-off.
 *
 * The opening turn is sent but not displayed, so what the customer sees is the
 * agent greeting them and offering the walkthrough — not a request they never
 * made sitting at the top of their chat history.
 *
 * `?blueprint-walkthrough=go` is that hand-off. It stays in the URL, because the
 * backend reads it on every turn of the session and because a site that has
 * already been through this does nothing with it — the record of a finished
 * walkthrough is what stops a repeat, not the absence of the flag.
 * `?blueprint-walkthrough=reset` runs it again, and `=images` jumps to the
 * photographs; both exist for testing and say so.
 */
export default function useBlueprintWalkthroughKickoff() {
	const { runAgent } = useDispatch( aiStore );
	const { isEditorIframeLoaded, isBuildingSite, messages } = useSelect(
		( select ) => ( {
			isEditorIframeLoaded: select( aiStore ).getIsEditorIframeLoaded(),
			isBuildingSite: select( aiStore ).getIsBuildingSite(),
			messages: select( aiStore ).getMessages(),
		} ),
		[]
	);

	const kickoffSentRef = useRef( false );

	// Whether this arrival is a rewrite, decided before anything is sent so the
	// canvas can be masked while the customer is still reading the greeting.
	const flagOnArrival = useRef(
		new URLSearchParams( window.location.search ).get(
			BLUEPRINT_WALKTHROUGH_PARAM
		)
	).current;

	// Only the copy rewrite masks. An images run leaves the text alone, so
	// blurring it would suggest work that is not happening.
	// The image run leaves the text alone, so blurring it would suggest work that
	// is not happening.
	useBlueprintCopyMask( flagOnArrival === 'go' || flagOnArrival === 'reset' );

	useEffect( () => {
		// Wait for the canvas: the agent's first move is to read the page
		// structure, and before the iframe is up that read comes back empty.
		if ( kickoffSentRef.current || ! isEditorIframeLoaded ) {
			return;
		}

		// Never talk over an existing conversation, and stay out of the way
		// while a build is still writing the page we are about to describe.
		if ( isBuildingSite || messages?.length > 0 ) {
			return;
		}

		const flag = new URLSearchParams( window.location.search ).get(
			BLUEPRINT_WALKTHROUGH_PARAM
		);
		if ( ! [ 'go', 'reset', 'images' ].includes( flag ) ) {
			return;
		}

		kickoffSentRef.current = true;

		// Every value stays in the URL: the backend reads it on each turn of the
		// session, and `go` is safe to see again because a site that has already
		// been through this simply does nothing with it.

		recordTracksEvent( 'big_sky_blueprint_walkthrough_kickoff' );
		runAgent( KICKOFF_MESSAGE, { hideUserMessage: true } );
	}, [ isEditorIframeLoaded, isBuildingSite, messages, runAgent ] );
}
