/**
 * External dependencies
 */
import deepmerge from 'deepmerge';

/**
 * WordPress dependencies
 */
import { useCallback, useEffect, useMemo } from '@wordpress/element';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { store as coreStore } from '@wordpress/core-data';
import { useDispatch, useSelect, select as wpSelect } from '@wordpress/data';

/**
 * Internal dependencies
 */
import {
	findLegacyBlocksInStylesValue,
	omitCustomCss,
	readCustomCss,
	removeLegacyBlocks,
	writeCustomCss,
} from '@shared/legacy-style-variation-css';
import {
	getStyleValue as getStyle,
	setStyleValue as setStyle,
} from '@utils/global-styles';
import { recordTracksEvent } from '@utils/tracks';
import useSiteMetadata from '@hooks/use-site-metadata';
import useVariations from '@hooks/use-variations';
import { store as aiStore } from '@store';
import { BIG_SKY_CUSTOM_THEME_PREFIX } from '@utils/custom-color-variations/constants';
import { getCanvasIframeElements } from '@utils/canvas-iframe-elements';
import useCurrentScreen from '@hooks/use-current-screen';

// Older versions of the Easy Site Editor persisted a scoped `!important` block
// into the user's Additional CSS, which then overrode anything picked
// afterwards — including in this plugin's pickers (ESE-20). Surface it once per
// session rather than on every apply; the pickers are built for rapid
// try-this-try-that browsing and a dialog per click would read as broken.
// Module scope, so a page load resets it.
//
// This latches on having *checked*, not on having found something, so the
// common case (no legacy CSS) scans once per session instead of on every pick.
// Safe because the answer cannot change mid-session: nothing writes the block
// any more.
let hasCheckedLegacyCssThisSession = false;

/**
 * Scan the user's Additional CSS for a legacy block, at most once per session.
 *
 * Returns an empty array when there is nothing to report — including when the
 * scan has already run, or when it threw (detection is advisory and must never
 * break an apply; leaving the flag clear lets the next apply retry).
 *
 * @param {unknown} cssValue A `styles.css` value.
 * @return {Array} Blocks found, or an empty array.
 */
function detectLegacyCss( cssValue ) {
	if ( hasCheckedLegacyCssThisSession ) {
		return [];
	}

	try {
		const blocks = findLegacyBlocksInStylesValue( cssValue );
		// Set only after the scan returned, so a throw leaves the flag clear.
		hasCheckedLegacyCssThisSession = true;
		return blocks;
	} catch {
		return [];
	}
}

// Test seam: the flag is module state, so tests need a way back to a clean
// slate between cases.
export function resetLegacyCssSessionFlag() {
	hasCheckedLegacyCssThisSession = false;
}

export default function useStyles() {
	const { currentColor, currentFont, currentButtonStyle } =
		useSiteMetadata().getSiteMetadata();
	const {
		setInitializedCustomScheme,
		pushGeneratedVariations,
		setCurrentColor: setCurrentColorState,
		setCurrentFont: setCurrentFontState,
		setCurrentButtonStyle: setCurrentButtonStyleState,
		setCurrentPaletteColors,
		setLegacyCssBlocks,
	} = useDispatch( aiStore );
	const { isDistractionFree } = useSelect(
		( select ) => ( {
			isDistractionFree:
				select( blockEditorStore ).getSettings().isDistractionFree,
		} ),
		[]
	);
	const { editEntityRecord, saveEditedEntityRecord } =
		useDispatch( coreStore );
	const { setCurrentColor, setCurrentFont, setCurrentButtonStyle } =
		useSiteMetadata();
	const { globalStylesId, getEntityRecord, getEditedEntityRecord } =
		useSelect( ( select ) => ( {
			globalStylesId:
				select( coreStore ).__experimentalGetCurrentGlobalStylesId(),
			getEntityRecord: select( coreStore ).getEntityRecord,
			getEditedEntityRecord: select( coreStore ).getEditedEntityRecord,
		} ) );

	const {
		getColorVariations,
		getFontVariations,
		getFontVariationByTitle,
		getButtonVariationByTitle,
	} = useVariations();
	const variations = useSelect( ( select ) => {
		return select(
			coreStore
		).__experimentalGetCurrentThemeGlobalStylesVariations();
	}, [] );
	const {
		getCurrentColor,
		getCurrentFont,
		getCurrentButtonStyle,
		getInitializedCustomScheme,
		getCustomVariationTemplates,
		getGeneratedVariations,
		getGoogleFonts,
		isEditorIframeLoaded,
	} = useSelect( ( select ) => {
		const ai = select( aiStore );
		return {
			currentPaletteColors: ai.getCurrentPaletteColors(),
			getCurrentColor: ai.getCurrentColor,
			getCurrentFont: ai.getCurrentFont,
			getCurrentButtonStyle: ai.getCurrentButtonStyle,
			getInitializedCustomScheme: ai.getInitializedCustomScheme,
			getUserStyleWithSettings: ai.getUserStyleWithSettings,
			getCustomVariationTemplates: ai.getCustomVariationTemplates,
			getGeneratedVariations: ai.getGeneratedVariations,
			getGoogleFonts: ai.getGoogleFonts,
			isEditorIframeLoaded: ai.getIsEditorIframeLoaded(),
			isEditorReady: ai.getIsEditorReady(),
		};
	} );
	const { coreColors, themeColors, customColors } = useSelect(
		( select ) => {
			const globalStyles = select( coreStore ).getEditedEntityRecord(
				'root',
				'globalStyles',
				globalStylesId
			);
			return {
				coreColors: globalStyles?.settings?.color?.palette?.core,
				themeColors: globalStyles?.settings?.color?.palette?.theme,
				customColors: globalStyles?.settings?.color?.palette?.custom,
			};
		},
		[ globalStylesId ]
	);
	const { isPostEditor } = useCurrentScreen();

	const paletteColors = useMemo(
		() => [
			...( customColors || [] ),
			...( themeColors || [] ),
			...( coreColors || [] ),
		],
		[ customColors, themeColors, coreColors ]
	);

	// Get custom CSS from global styles using getStyle
	const customCss = useSelect(
		( select ) => {
			const globalStyles = select( coreStore ).getEditedEntityRecord(
				'root',
				'globalStyles',
				globalStylesId
			);
			return getStyle( globalStyles, 'css', null, false );
		},
		[ globalStylesId ]
	);

	const useCustomCss = useCallback(
		() => [
			typeof customCss === 'string' ? customCss : customCss?.css || '',
			( css ) => {
				// Use setStyle to update the custom CSS
				const currentGlobalStyles = getEditedEntityRecord(
					'root',
					'globalStyles',
					globalStylesId
				);
				const updatedGlobalStyles = setStyle(
					currentGlobalStyles,
					'css',
					css
				);
				// Update the entity record with the new styles
				editEntityRecord(
					'root',
					'globalStyles',
					globalStylesId,
					updatedGlobalStyles
				);
			},
		],
		[ customCss, editEntityRecord, getEditedEntityRecord, globalStylesId ]
	);

	const resetStyles = () => {
		// Try to get globalStylesId fresh in case it wasn't available at hook init
		// (can happen in Calypso where global styles load after the hook initializes)
		const currentGlobalStylesId =
			globalStylesId ||
			wpSelect( coreStore ).__experimentalGetCurrentGlobalStylesId?.();

		if ( currentGlobalStylesId ) {
			// Gutenberg 22.0.0: No longer using useGlobalStylesReset hook
			// Reset styles using entity record API directly
			editEntityRecord( 'root', 'globalStyles', currentGlobalStylesId, {
				id: currentGlobalStylesId,
				settings: {},
				styles: {},
			} );
			saveEditedEntityRecord(
				'root',
				'globalStyles',
				currentGlobalStylesId
			);
		}
	};

	const getCurrentTheme = useCallback( () => {
		const globalStyles = getEditedEntityRecord(
			'root',
			'globalStyles',
			globalStylesId
		);
		return globalStyles;
	}, [ getEditedEntityRecord, globalStylesId ] );

	const setStyles = useCallback(
		( parameters ) => {
			const { color, font, button, undoIgnore = false } = parameters;

			let selectedColorTitle = color || getCurrentColor() || currentColor;
			let selectedFontTitle = font || getCurrentFont() || currentFont;
			const selectedButtonStyle =
				button || getCurrentButtonStyle() || currentButtonStyle;

			const colors = getColorVariations();
			// Check to make sure both the font and color are valid
			// If either are not valid, set them to a random color or font title
			if ( ! colors?.find( ( c ) => c.title === selectedColorTitle ) ) {
				selectedColorTitle =
					// eslint-disable-next-line
					colors[ Math.floor( Math.random() * colors.length ) ]
						?.title;
			}

			// I would love to get rid of the `variations` here, but if we do that, we
			// have few renders where colors/fonts is undefined at the start of the app.
			const colorVariation = ( colors ?? variations )?.find(
				( v ) => v.title === selectedColorTitle
			);
			if ( color ) {
				setCurrentColor( selectedColorTitle );
				setCurrentColorState( selectedColorTitle );

				const colorPalette =
					colorVariation?.settings?.color?.palette?.theme;
				setCurrentPaletteColors( colorPalette );
			}

			const fonts = getFontVariations();
			if ( ! fonts?.find( ( f ) => f.title === selectedFontTitle ) ) {
				selectedFontTitle =
					// eslint-disable-next-line
					fonts[ Math.floor( Math.random() * fonts.length ) ]?.title;
			}
			const fontVariation = ( fonts ?? variations )?.find(
				( v ) => v.title === selectedFontTitle
			);
			if ( font ) {
				setCurrentFont( selectedFontTitle );
				setCurrentFontState( selectedFontTitle );
			}

			if ( button ) {
				setCurrentButtonStyle( button );
				setCurrentButtonStyleState( button );
			}

			const buttonVariation =
				getButtonVariationByTitle( selectedButtonStyle );

			// Get current config from the edited entity record
			let currentConfig = getEditedEntityRecord(
				'root',
				'globalStyles',
				globalStylesId
			);

			// Custom merge options to handle arrays properly
			const mergeOptions = {
				arrayMerge: ( destinationArray, sourceArray ) => sourceArray,
			};

			// if the font is changing, remove the typography key from all relevant objects
			// this prevents any existing typography styles from being applied to the new font
			if ( font ) {
				const removeTypography = ( obj ) => {
					if ( ! obj || typeof obj !== 'object' ) return obj;

					const result = { ...obj };

					// Handle both styles.elements and styles.blocks
					if ( result.styles ) {
						const sections = {
							...result,
							...result.styles.elements,
							...result.styles.blocks,
						};

						for ( const [ , value ] of Object.entries(
							sections
						) ) {
							if ( value?.typography ) {
								delete value.typography;
							}
						}
					}

					return result;
				};

				currentConfig = removeTypography( currentConfig );
			}

			// if the button is changing, remove the button styles from the current config
			if ( button ) {
				const processButtonStyles = ( obj ) => {
					if ( ! obj || typeof obj !== 'object' ) return obj;

					const result = { ...obj };

					// Handle styles.elements.button
					if ( result.styles?.elements?.button ) {
						const buttonElement = result.styles.elements.button;

						// Copy color to buttonColor if it has !important and buttonColor doesn't exist
						if (
							buttonVariation?.styles?.elements?.button?.color?.background.includes(
								'!important'
							) &&
							buttonVariation?.styles?.elements?.button?.color?.text.includes(
								'!important'
							) &&
							! buttonElement.buttonColor
						) {
							buttonElement.buttonColor = buttonElement.color;
						}

						// Remove border and spacing properties
						delete buttonElement.border;
						delete buttonElement.spacing;

						// Restore color from buttonColor if current color has !important
						if (
							buttonElement.color?.background?.includes(
								'!important'
							) &&
							buttonElement.color?.text?.includes(
								'!important'
							) &&
							buttonElement.buttonColor
						) {
							buttonElement.color = buttonElement.buttonColor;
						}
					}

					// Handle styles.blocks variations
					if ( result.styles?.blocks ) {
						Object.values( result.styles.blocks ).forEach(
							( block ) => {
								if ( block.variations ) {
									Object.values( block.variations ).forEach(
										( variation ) => {
											if ( variation.elements?.button ) {
												delete variation.elements.button
													.border;
												delete variation.elements.button
													.spacing;
											}
										}
									);
								}
							}
						);
					}

					return result;
				};

				currentConfig = processButtonStyles( currentConfig );
			}

			const newConfig = {
				settings: [
					currentConfig?.settings,
					color ? colorVariation?.settings : null,
					font ? fontVariation?.settings : null,
				]
					.filter( Boolean )
					.reduce(
						( acc, curr ) => deepmerge( acc, curr, mergeOptions ),
						{}
					),
				styles: [
					currentConfig?.styles,
					color ? colorVariation?.styles : null,
					font ? fontVariation?.styles : null,
					button ? buttonVariation?.styles : null,
				]
					.filter( Boolean )
					.reduce(
						( acc, curr ) => deepmerge( acc, curr, mergeOptions ),
						{}
					),
			};

			// add button styles to jetpack/subscriptions block
			if ( buttonVariation?.styles?.elements ) {
				// Helper function to add !important to style values
				const addImportantToStyles = ( obj ) => {
					if ( ! obj || typeof obj !== 'object' ) return obj;

					const result = {};
					for ( const [ key, value ] of Object.entries( obj ) ) {
						// Match the button height of the Jetpack input fields
						if ( key === 'top' || key === 'bottom' ) {
							continue;
						}
						if ( typeof value === 'object' && value !== null ) {
							result[ key ] = addImportantToStyles( value );
						} else if (
							typeof value === 'string' &&
							! value.includes( '!important' )
						) {
							result[ key ] = `${ value } !important`;
						} else {
							result[ key ] = value;
						}
					}
					return result;
				};

				newConfig.styles.blocks = {
					...newConfig.styles.blocks,
					'jetpack/subscriptions': {
						elements: addImportantToStyles(
							buttonVariation.styles.elements
						),
					},
				};
			}

			// Update the global styles entity with the new config
			editEntityRecord(
				'root',
				'globalStyles',
				globalStylesId,
				{
					settings: newConfig.settings,
					styles: newConfig.styles,
				},
				{ undoIgnore }
			);

			// Update the title of the global styles entity
			editEntityRecord(
				'root',
				'globalStyles',
				globalStylesId,
				{
					title: selectedColorTitle,
				},
				{ undoIgnore: true }
			);

			// Font picks only. The persisted block contains font-family,
			// font-weight and font-style and nothing else — every version that
			// wrote it emitted typography exclusively — so it cannot override a
			// colour or button style the user just chose. Warning about it then
			// would point at CSS that provably can't affect their change.
			if ( font ) {
				const blocks = detectLegacyCss( newConfig.styles?.css );
				if ( blocks.length ) {
					recordTracksEvent( 'legacy_css_found', {
						block_count: blocks.length,
					} );
					setLegacyCssBlocks( blocks );
				}
			}

			if ( isPostEditor ) {
				const { canvasiFrameDocument } = getCanvasIframeElements();
				let style =
					canvasiFrameDocument.getElementById( 'big-sky-colors' );
				if ( ! style ) {
					style = canvasiFrameDocument.createElement( 'style' );
					style.setAttribute( 'id', 'big-sky-colors' );
					canvasiFrameDocument.body.appendChild( style );
				}
				const styleRules = [];

				const colorPalette = getEditedEntityRecord(
					'root',
					'globalStyles',
					globalStylesId
				).settings.color.palette.theme;
				// add style overrides for .has-theme-n-background-color classes
				colorPalette.forEach( ( c ) => {
					styleRules.push(
						`.has-${ c.slug }-background-color {
						background-color: ${ c.color } !important;
					}`
					);
					styleRules.push(
						`.has-${ c.slug }-color {
						color: ${ c.color } !important;
					}`
					);
				} );
				style.textContent = styleRules.join( '\n' );
			}

			return {
				selectedColorVariation: selectedColorTitle,
				selectedFontVariation: selectedFontTitle,
			};
		},
		[
			currentColor,
			currentFont,
			currentButtonStyle,
			editEntityRecord,
			getButtonVariationByTitle,
			getColorVariations,
			getCurrentColor,
			getCurrentFont,
			getCurrentButtonStyle,
			getEditedEntityRecord,
			getFontVariations,
			globalStylesId,
			isPostEditor,
			setCurrentColor,
			setCurrentColorState,
			setCurrentFont,
			setCurrentFontState,
			setCurrentButtonStyle,
			setCurrentButtonStyleState,
			setCurrentPaletteColors,
			setLegacyCssBlocks,
			variations,
		]
	);

	// Stage removal of the legacy blocks. Read the record at call time and
	// spread the existing styles: `editEntityRecord` replaces the whole `styles`
	// key rather than merging, and the variation the user just applied is still
	// an unsaved edit, so reading a stale copy here would revert it. The edit is
	// staged, not saved — it rides along with their next save, exactly like the
	// apply that triggered the dialog.
	const removeLegacyCss = useCallback( () => {
		setLegacyCssBlocks( [] );

		if ( ! globalStylesId ) {
			return;
		}

		const record = getEditedEntityRecord(
			'root',
			'globalStyles',
			globalStylesId
		);
		const styles =
			record?.styles && typeof record.styles === 'object'
				? record.styles
				: undefined;

		if ( ! styles ) {
			return;
		}

		const css = readCustomCss( styles.css );
		if ( css === null ) {
			return;
		}

		const cleaned = removeLegacyBlocks(
			css,
			findLegacyBlocksInStylesValue( styles.css )
		);

		editEntityRecord( 'root', 'globalStyles', globalStylesId, {
			styles: cleaned.trim()
				? { ...styles, css: writeCustomCss( styles.css, cleaned ) }
				: omitCustomCss( styles ),
		} );
	}, [
		editEntityRecord,
		getEditedEntityRecord,
		globalStylesId,
		setLegacyCssBlocks,
	] );

	const dismissLegacyCssNotice = useCallback( () => {
		setLegacyCssBlocks( [] );
	}, [ setLegacyCssBlocks ] );

	// this is a workaround in order to sync the color palette name with Big Sky
	// adds an click event listener on the palette panel
	useEffect( () => {
		if ( ! isEditorIframeLoaded || isDistractionFree ) {
			return;
		}

		const handleClick = ( event ) => {
			const variationItem = event.target.closest(
				'.edit-site-global-styles-variations_item'
			);
			if ( variationItem ) {
				const ariaLabel = variationItem.getAttribute( 'aria-label' );

				// this part is a bit brittle, but not sure if there's a better way to do this
				const subtitle = event.target
					.closest( '.components-grid' )
					?.previousElementSibling?.textContent.trim()
					.toLowerCase();
				switch ( subtitle ) {
					case 'palettes':
						setCurrentColor( ariaLabel );
						setCurrentColorState( ariaLabel );
						break;
					case 'typesets':
						setCurrentFont( ariaLabel );
						setCurrentFontState( ariaLabel );
						break;
					default:
						// do nothing
						break;
				}
			}
		};

		// Helper function to check if a node or any of its children contain a class
		const hasClassRecursively = ( node, classNames ) => {
			if ( ! node || node.node_type !== window.Node.ELEMENT_NODE )
				return false;

			// Convert single class name to array for consistent handling
			const classesToCheck = Array.isArray( classNames )
				? classNames
				: [ classNames ];

			// Check the node itself
			if ( node.classList ) {
				for ( const className of classesToCheck ) {
					if ( node.classList.contains( className ) ) {
						return true;
					}
				}
			}

			// Check all children recursively
			for ( const child of node.children ) {
				if ( hasClassRecursively( child, classesToCheck ) ) {
					return true;
				}
			}

			return false;
		};

		const observer = new window.MutationObserver( ( mutations ) => {
			// Only process mutations that add the color palette or typography panel
			const relevantMutation = mutations.find(
				( mutation ) =>
					mutation.addedNodes.length > 0 &&
					Array.from( mutation.addedNodes ).some( ( node ) =>
						hasClassRecursively( node, [
							'edit-site-global-styles-color-palette-panel',
							'edit-site-global-styles-style-variations-container',
						] )
					)
			);
			if ( relevantMutation ) {
				const panel = Array.from( relevantMutation.addedNodes ).find(
					( node ) =>
						hasClassRecursively( node, [
							'edit-site-global-styles-color-palette-panel',
							'edit-site-global-styles-style-variations-container',
						] )
				);
				if (
					panel &&
					! panel.hasAttribute( 'data-has-click-listener' )
				) {
					panel.addEventListener( 'click', handleClick );
					panel.setAttribute( 'data-has-click-listener', 'true' );
				}
			}
		} );

		const sidebar = document.querySelector(
			'.interface-interface-skeleton__sidebar'
		);
		if ( sidebar ) {
			// target the sidebar .interface-interface-skeleton__sidebar
			observer.observe( sidebar, {
				childList: true,
				subtree: true,
				attributes: false, // Don't observe attribute changes
				characterData: false, // Don't observe text changes
			} );
		}

		return () => {
			observer.disconnect();
		};
	}, [
		isEditorIframeLoaded,
		isDistractionFree,
		editEntityRecord,
		globalStylesId,
		setCurrentColor,
		setCurrentColorState,
		setCurrentFont,
		setCurrentFontState,
	] );

	/**
	 * Creates a font variation from the current font string
	 * @param {string} fontString - Font string like "Reggae One 400 + Raleway 400"
	 * @return {Object|null} Font variation object or null if creation fails
	 */
	const createFontVariationFromCurrentFont = useCallback(
		( fontString ) => {
			if ( ! fontString ) return null;

			// Parse the font string to extract font names and weights
			// Format: "Font Name 400 + Font Name 400"
			const fontPairMatch = fontString.match(
				/^(.+?)\s+(\d+)\s+\+\s+(.+?)\s+(\d+)$/
			);
			if ( ! fontPairMatch ) return null;

			const [
				,
				headingFontName,
				headingWeight,
				bodyFontName,
				bodyWeight,
			] = fontPairMatch;

			// Get Google Fonts data from the store
			const googleFontsData = getGoogleFonts();

			if ( ! googleFontsData?.font_families ) {
				console.warn( 'Google Fonts data not available' );
				return null;
			}

			// Find the font family objects
			const headingFont = googleFontsData.font_families.find(
				( font ) => font.font_family_settings.name === headingFontName
			);
			const bodyFont = googleFontsData.font_families.find(
				( font ) => font.font_family_settings.name === bodyFontName
			);

			if ( ! headingFont || ! bodyFont ) {
				console.warn( 'Font families not found in Google Fonts data' );
				return null;
			}

			// Create the font variation object
			const variation = {
				title: fontString,
				version: 3,
				settings: {
					typography: {
						fontFamilies: {
							theme: [
								headingFont.font_family_settings,
								bodyFont.font_family_settings,
							],
						},
					},
				},
				styles: {
					typography: {
						fontFamily: bodyFont.font_family_settings.name,
						fontWeight: bodyWeight,
						fontStyle: 'normal',
					},
					elements: {
						heading: {
							typography: {
								fontFamily:
									headingFont.font_family_settings.name,
								fontWeight: headingWeight,
								fontStyle: 'normal',
							},
						},
						button: {
							typography: {
								fontFamily:
									headingFont.font_family_settings.name,
								fontWeight: headingWeight,
								fontStyle: 'normal',
							},
						},
					},
				},
			};

			return variation;
		},
		[ getGoogleFonts ]
	);

	// Push the existing palette colors to the generated variations on initialization
	// This ensures we always have a Custom Scheme in the palette
	useEffect( () => {
		if (
			! getCustomVariationTemplates().length ||
			getInitializedCustomScheme() ||
			( ! isEditorIframeLoaded && ! isPostEditor )
		) {
			return;
		}

		// always create a variation for the current font pair
		// Check to see if the current font variation already exists
		const allFontVariations = getFontVariations();
		let currentFontVariation = allFontVariations.find(
			( v ) => v.title === currentFont
		);

		// If the current font variation doesn't exist, create it dynamically
		if ( ! currentFontVariation && currentFont ) {
			currentFontVariation =
				createFontVariationFromCurrentFont( currentFont );
		}

		if (
			currentFontVariation &&
			! getGeneratedVariations().some(
				( v ) => v.title === currentFontVariation.title
			)
		) {
			pushGeneratedVariations( [ currentFontVariation ] );
		}

		// always create a variation for a custom theme
		const currentThemeCopy = JSON.parse(
			JSON.stringify( getCurrentTheme() )
		);
		if ( currentThemeCopy ) {
			currentThemeCopy.title = currentColor?.startsWith(
				BIG_SKY_CUSTOM_THEME_PREFIX
			)
				? currentColor
				: BIG_SKY_CUSTOM_THEME_PREFIX;
			pushGeneratedVariations( [ currentThemeCopy ] );
		}
		setCurrentPaletteColors( paletteColors );
		setInitializedCustomScheme( true );
	}, [
		currentColor,
		currentFont,
		paletteColors,
		getCustomVariationTemplates,
		getEntityRecord,
		getInitializedCustomScheme,
		globalStylesId,
		pushGeneratedVariations,
		setInitializedCustomScheme,
		setCurrentPaletteColors,
		getCurrentTheme,
		setStyles,
		isEditorIframeLoaded,
		isPostEditor,
		getFontVariations,
		getFontVariationByTitle,
		getGeneratedVariations,
		createFontVariationFromCurrentFont,
	] );

	return {
		getCurrentTheme,
		resetStyles,
		setStyles,
		themeColors,
		useCustomCss,
		removeLegacyCss,
		dismissLegacyCssNotice,
	};
}
