/**
 * WordPress dependencies
 */
import { useDispatch, useSelect } from '@wordpress/data';
import { useEffect } from '@wordpress/element';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import useBuildSiteTool from '@ai/assistants/spec/tools/build-site/use-build-site-tool';
import useSpecProcessor from '@hooks/use-spec-processor';
import log from '@utils/log-debug';
import { removeUrlParam } from '@utils/url-params';

/**
 * Headless hook that triggers the site build once the editor canvas is ready
 * and a pending spec exists. Extracted from the Onboarding overlay so the build
 * runs independently of any visible onboarding UI.
 */
export default function useSiteBuildTrigger() {
	const { setHeaderSectionIsReady, setBigSkyPendingSpec, setIsBuildingSite } =
		useDispatch( aiStore );
	const { buildSiteTask } = useBuildSiteTool();
	const {
		isBuildingSite,
		isEditorIframeLoaded,
		pendingSpec,
		isProcessingSpec,
	} = useSelect(
		( select ) => ( {
			isBuildingSite: select( aiStore ).getIsBuildingSite(),
			isEditorIframeLoaded: select( aiStore ).getIsEditorIframeLoaded(),
			pendingSpec: select( aiStore ).getBigSkyPendingSpec(),
			isProcessingSpec: select( aiStore ).getIsProcessingSpec(),
		} ),
		[]
	);

	const searchParams = new URLSearchParams( window.location.search );
	const passedSpec = searchParams.get( 'spec_id' ) || '';

	// Process a spec passed via the spec_id URL param into a pending spec.
	useSpecProcessor( passedSpec );

	// Wait for the canvas to be ready before triggering the build.
	useEffect( () => {
		if (
			isEditorIframeLoaded &&
			pendingSpec &&
			! isBuildingSite &&
			! isProcessingSpec
		) {
			setIsBuildingSite( true );

			( async () => {
				try {
					setHeaderSectionIsReady( false );
					await buildSiteTask( pendingSpec );
					log.info( 'Build site triggered' );
					setBigSkyPendingSpec( null );
					removeUrlParam( 'spec_id' );
				} catch ( error ) {
					log.error( 'Error triggering build:', error );
					setIsBuildingSite( false );
					// Clear the pending spec and URL param so a failed trigger
					// doesn't immediately re-satisfy the effect condition
					// ( pendingSpec && ! isBuildingSite ) and loop build attempts.
					setBigSkyPendingSpec( null );
					removeUrlParam( 'spec_id' );
				}
			} )();
		}
	}, [
		isEditorIframeLoaded,
		setHeaderSectionIsReady,
		setIsBuildingSite,
		setBigSkyPendingSpec,
		pendingSpec,
		isBuildingSite,
		buildSiteTask,
		isProcessingSpec,
	] );
}
