/**
 * Block utility functions for working with WordPress blocks.
 */

/**
 * WordPress dependencies
 */
import { createBlock } from '@wordpress/blocks';

/**
 * Gets surrounding content of a block from in-memory blocks
 * @param {Array}  inMemoryBlocks - Array of blocks in memory
 * @param {Object} targetBlock    - Target block to find surrounding content for
 * @return {string} Concatenated content from surrounding blocks
 */
export const getSurroundingContentOfBlockInMemory = (
	inMemoryBlocks,
	targetBlock
) => {
	// If no block provided, return empty string
	if ( ! targetBlock ) {
		return '';
	}

	const findParentGroup = ( blocks, targetClientId, path = [] ) => {
		for ( const block of blocks ) {
			const currentPath = [ ...path, block ];

			// Found the block we're looking for
			if ( block.clientId === targetClientId ) {
				// Walk up the path to find the first core/group parent
				for ( let i = path.length - 1; i >= 0; i-- ) {
					if ( path[ i ].name === 'core/group' ) {
						return path[ i ];
					}
				}
				return null; // No core/group parent found
			}

			// Recurse into innerBlocks
			if ( block.innerBlocks && block.innerBlocks.length > 0 ) {
				const found = findParentGroup(
					block.innerBlocks,
					targetClientId,
					currentPath
				);
				if ( found ) return found;
			}
		}

		return null;
	};

	// Find the closest parent group block
	const parentGroup = findParentGroup( inMemoryBlocks, targetBlock.clientId );

	if ( ! parentGroup ) {
		return '';
	}

	// Helper function to recursively collect content from blocks
	const collectBlockContent = ( currentBlock ) => {
		const content = [];

		// Add content from current block if it's a content block
		if ( currentBlock.name === 'core/heading' ) {
			content.push( currentBlock.attributes.content );
		} else if ( currentBlock.name === 'core/paragraph' ) {
			content.push( currentBlock.attributes.content );
		} else if ( currentBlock.name === 'core/button' ) {
			content.push( currentBlock.attributes.text );
		}

		// Recursively collect content from inner blocks
		if ( currentBlock.innerBlocks?.length > 0 ) {
			currentBlock.innerBlocks.forEach( ( innerBlock ) => {
				content.push( ...collectBlockContent( innerBlock ) );
			} );
		}

		return content;
	};

	// Get content from the parent group's inner blocks
	const content = [];
	parentGroup.innerBlocks.forEach( ( innerBlock ) => {
		content.push( ...collectBlockContent( innerBlock ) );
	} );

	return content.join( ' ' );
};

/**
 * Extract href from HTML string (e.g. from block innerHTML).
 *
 * @param {string} html - HTML string containing an anchor
 * @return {string|undefined} Extracted href or undefined
 */
function extractHrefFromHtml( html ) {
	if ( typeof html !== 'string' ) return undefined;
	const match = html.match( /href=["']([^"']+)["']/ );
	return match ? match[ 1 ] : undefined;
}

/**
 * Normalize block attributes for insertion.
 * Handles common issues from parsed/AI-generated block data:
 * - attributes as empty array [] -> {}
 * - core/button: content -> text (block editor uses text)
 * - core/button: extract url from innerHTML when missing in attributes
 * - jetpack/map: drop points the block's own save() would throw on
 *
 * @param {string} blockName  - Block name
 * @param {Object} attributes - Raw attributes
 * @param {Object} options    - Optional { innerHTML } for extraction fallbacks
 * @return {Object} Normalized attributes object
 */
function normalizeBlockAttributes( blockName, attributes, options = {} ) {
	const raw = attributes;
	if ( Array.isArray( raw ) || raw === null || raw === undefined ) {
		return {};
	}
	const attrs = { ...raw };

	if ( blockName === 'core/button' ) {
		if (
			attrs.content !== null &&
			attrs.content !== undefined &&
			( attrs.text === null || attrs.text === undefined )
		) {
			attrs.text = attrs.content;
		}
		if (
			( attrs.url === null || attrs.url === undefined ) &&
			options.innerHTML
		) {
			const href = extractHrefFromHtml( options.innerHTML );
			if ( href ) {
				attrs.url = href;
			}
		}
	}

	// The map's save() destructures point.coordinates for every entry of
	// points, so one point without it throws — and save() runs outside block
	// validation, which is the only caller that catches it. The person gets a
	// page that will not open, from the one place they could have undone it.
	// Site build reaches here with whatever the layout service generated for a
	// location we could not geocode, which is where we have seen it.
	if ( blockName === 'jetpack/map' && 'points' in attrs ) {
		attrs.points = (
			Array.isArray( attrs.points ) ? attrs.points : []
		).filter(
			( point ) =>
				Number.isFinite( point?.coordinates?.longitude ) &&
				Number.isFinite( point?.coordinates?.latitude )
		);
	}

	return attrs;
}

/**
 * Recursively recreates a block using WordPress createBlock to generate proper clientId and validation properties.
 * This is useful when working with block data from external sources that need to be properly registered.
 * Normalizes attributes (handles [] and core/button content->text) before creating.
 *
 * @param {Object} block - Block to recreate
 * @return {Object} New block with proper WordPress validation
 */
export const recreateBlock = ( block ) => {
	if ( ! block ) return block;

	// Recursively recreate inner blocks first
	const innerBlocks =
		block.innerBlocks && Array.isArray( block.innerBlocks )
			? block.innerBlocks.map( recreateBlock )
			: [];

	const attributes = normalizeBlockAttributes(
		block.name,
		block.attributes || {},
		{ innerHTML: block.innerHTML }
	);

	// Use WordPress createBlock to generate proper clientId and validation properties
	return createBlock( block.name, attributes, innerBlocks );
};
