/**
 * Utility functions for reading and writing global styles data.
 * These provide the same functionality as @wordpress/global-styles-engine introduced in Gutenberg 22.0.0,
 * but work with any Gutenberg version without requiring that package.
 */

/**
 * Get a style value from the global styles object using a path string.
 * Optionally resolves CSS variables to their actual values.
 *
 * @param {Object}  globalStyles              - The global styles object
 * @param {string}  path                      - Dot-separated path to the style value (e.g., 'color.text')
 * @param {string}  [blockName]               - Optional block name for block-specific styles (e.g., 'core/button')
 * @param {boolean} [shouldDecodeEncode=true] - Whether to resolve CSS variables to actual values
 * @return {*} The style value or undefined if not found
 *
 * @example
 * // Get global text color (with CSS variable resolution)
 * const textColor = getStyleValue(globalStyles, 'color.text');
 *
 * // Get raw CSS variable without resolution
 * const rawValue = getStyleValue(globalStyles, 'color.text', undefined, false);
 *
 * // Get button background color
 * const buttonBg = getStyleValue(globalStyles, 'color.background', 'core/button');
 */
export function getStyleValue(
	globalStyles,
	path,
	blockName = null,
	shouldDecodeEncode = true
) {
	if ( ! globalStyles ) {
		return undefined;
	}

	// Split the path into segments
	const segments = path.split( '.' );

	// If blockName is provided, look in blocks or elements section
	if ( blockName ) {
		// Handle block-specific styles (e.g., 'core/button')
		if ( blockName.includes( '/' ) ) {
			const blockPath = [ 'styles', 'blocks', blockName, ...segments ];
			return getNestedValue( globalStyles, blockPath );
		}

		// Handle element styles (e.g., 'button', 'heading', 'h1')
		// Map block names to element names
		const elementName = blockName
			.replace( 'core/', '' )
			.replace( 'heading:', '' );
		const elementPath = [ 'styles', 'elements', elementName, ...segments ];
		const value = getNestedValue( globalStyles, elementPath );
		if ( shouldDecodeEncode && value && typeof value === 'string' ) {
			return resolveCSSVariable( value, globalStyles );
		}
		return value;
	}

	// Look in global styles (only when no blockName specified)
	const globalPath = [ 'styles', ...segments ];
	const value = getNestedValue( globalStyles, globalPath );

	// Resolve CSS variables if requested
	if ( shouldDecodeEncode && value && typeof value === 'string' ) {
		return resolveCSSVariable( value, globalStyles );
	}

	return value;
}

/**
 * Resolve CSS variable to its actual value.
 * Supports color presets like var(--wp--preset--color--theme-1).
 *
 * @param {string} value        - The CSS variable string
 * @param {Object} globalStyles - The global styles object for lookup
 * @return {string} The resolved value or original if not a variable
 */
function resolveCSSVariable( value, globalStyles ) {
	// Check if it's a CSS variable
	if ( ! value.includes( 'var(--wp--preset' ) ) {
		return value;
	}

	// Extract the variable name
	// Format: var(--wp--preset--color--theme-1)
	// Note: preset type can include hyphens (e.g. font-family, font-size).
	const match = value.match( /var\(--wp--preset--([a-z-]+)--(.+?)\)/i );
	if ( ! match ) {
		return value;
	}

	const [ , presetType, slug ] = match;

	// Look up the value in settings based on preset type
	let presetPath;
	switch ( presetType ) {
		case 'color':
			presetPath = [ 'settings', 'color', 'palette', 'theme' ];
			break;
		case 'font-size':
			presetPath = [ 'settings', 'typography', 'fontSizes', 'theme' ];
			break;
		case 'font-family':
			presetPath = [ 'settings', 'typography', 'fontFamilies', 'theme' ];
			break;
		default:
			return value;
	}

	const presets = getNestedValue( globalStyles, presetPath );
	if ( ! presets || ! Array.isArray( presets ) ) {
		return value;
	}

	// Find the preset with matching slug.
	const preset = presets.find( ( p ) => p.slug === slug );
	if ( ! preset ) {
		return value;
	}

	// Return the appropriate property based on preset type
	switch ( presetType ) {
		case 'color':
			return preset.color || value;
		case 'font-size':
			return preset.size || value;
		case 'font-family':
			return preset.name || preset.fontFamily || value;
		default:
			return value;
	}
}

/**
 * Set a style value in the global styles object using a path string.
 * Returns a new object with the updated value (immutable).
 *
 * @param {Object} globalStyles - The global styles object
 * @param {string} path         - Dot-separated path to the style value (e.g., 'color.text')
 * @param {*}      value        - The new value to set
 * @param {string} [blockName]  - Optional block name for block-specific styles
 * @return {Object} New global styles object with the updated value
 *
 * @example
 * // Set global text color
 * const updated = setStyleValue(globalStyles, 'color.text', '#333');
 *
 * // Set button background color
 * const updated = setStyleValue(globalStyles, 'color.background', '#blue', 'core/button');
 */
export function setStyleValue( globalStyles, path, value, blockName = null ) {
	if ( ! globalStyles ) {
		return globalStyles;
	}

	// Split the path into segments
	const segments = path.split( '.' );

	// Determine the full path based on blockName
	let fullPath;
	if ( blockName ) {
		if ( blockName.includes( '/' ) ) {
			// Block-specific path (e.g., 'core/button')
			fullPath = [ 'styles', 'blocks', blockName, ...segments ];
		} else {
			// Element path (e.g., 'button', 'heading')
			fullPath = [ 'styles', 'elements', blockName, ...segments ];
		}
	} else {
		// Global styles path
		fullPath = [ 'styles', ...segments ];
	}

	return setNestedValue( globalStyles, fullPath, value );
}

/**
 * Helper function to get a nested value from an object using an array of keys.
 *
 * @param {Object}        obj  - The object to traverse
 * @param {Array<string>} path - Array of keys representing the path
 * @return {*} The value at the path or undefined
 */
function getNestedValue( obj, path ) {
	return path.reduce( ( current, key ) => {
		return current?.[ key ];
	}, obj );
}

/**
 * Helper function to set a nested value in an object immutably.
 * Returns a new object with the updated value.
 *
 * @param {Object}        obj   - The object to update
 * @param {Array<string>} path  - Array of keys representing the path
 * @param {*}             value - The value to set
 * @return {Object} New object with the updated value
 */
function setNestedValue( obj, path, value ) {
	if ( path.length === 0 ) {
		return value;
	}

	const [ head, ...tail ] = path;
	const currentValue = obj[ head ];

	// Recursively build the nested structure
	const newValue =
		tail.length === 0
			? value
			: setNestedValue(
					currentValue && typeof currentValue === 'object'
						? currentValue
						: {},
					tail,
					value
			  );

	// Return new object with updated value
	return {
		...obj,
		[ head ]: newValue,
	};
}
