// Detection and removal of the legacy style-variation CSS block that older
// versions of the Easy Site Editor injected into the user's Additional CSS
// (`styles.css`) on every font/colour apply:
//
//   /* easy-site-editor-style-variation:start */
//   body .wp-site-blocks h1, … {font-family:var(--wp--preset--…) !important;}
//   /* easy-site-editor-style-variation:end */
//
// That block permanently overrode any font or colour the user later picked —
// in the Easy Site Editor, in the main Big Sky plugin, and in the core Site
// Editor (ESE-20). We stopped writing it, but deliberately do not strip it
// automatically: the marker lives in a user-editable field, so a blind strip
// risks deleting CSS the user wrote between the start and end.
//
// Instead the pickers use this module to detect the block and show the user
// exactly what it contains, so they can decide. Informed consent is what makes
// removal safe here — everything below assumes a human is going to read the
// text we return before agreeing to delete it.

// An earlier `/* easy-site-editor-fonts:… */` marker existed in the source
// between 2026-05-05 and 2026-05-13, but the editor did not reach users until
// after 21 May, so no site can carry it. Only this pair is worth detecting.
export const LEGACY_CSS_START = '/* easy-site-editor-style-variation:start */';
export const LEGACY_CSS_END = '/* easy-site-editor-style-variation:end */';

export interface LegacyBlock {
	/** Index the removal starts at, including any absorbed leading whitespace. */
	start: number;
	/** Index just past the closing marker. */
	end: number;
	/** The block as it should be shown to the user, without leading blank lines. */
	text: string;
}

function isRecord( value: unknown ): value is Record< string, unknown > {
	return !! value && typeof value === 'object' && ! Array.isArray( value );
}

/**
 * Find every well-formed legacy block in a stylesheet.
 *
 * Pairs each start marker with the *nearest* following end marker and resumes
 * the scan past it, so the blocks returned are always sequential and
 * non-overlapping. A start marker with no matching end is skipped: its extent
 * is unknowable, so no removal we could offer would be safe.
 *
 * An empty result is the single signal for "there is nothing to tell the user
 * about" — it covers no markers, orphaned markers, and already-cleaned sites.
 *
 * @param css The stylesheet to scan.
 * @return Blocks in document order.
 */
export function findLegacyBlocks( css: string ): LegacyBlock[] {
	if ( typeof css !== 'string' || ! css ) {
		return [];
	}

	const found: LegacyBlock[] = [];
	let from = 0;

	for (;;) {
		const markerStart = css.indexOf( LEGACY_CSS_START, from );
		if ( markerStart === -1 ) {
			break;
		}

		const endIndex = css.indexOf(
			LEGACY_CSS_END,
			markerStart + LEGACY_CSS_START.length
		);
		if ( endIndex === -1 ) {
			// Orphaned start marker — nothing safe left to find.
			break;
		}

		const end = endIndex + LEGACY_CSS_END.length;

		// Absorb preceding whitespace so removal doesn't leave a gap where the
		// block used to be.
		let start = markerStart;
		while ( start > 0 && /\s/.test( css[ start - 1 ] ) ) {
			start--;
		}

		found.push( {
			start,
			end,
			text: css.slice( start, end ).trim(),
		} );
		from = end;
	}

	return found;
}

/**
 * Remove the given blocks from a stylesheet.
 *
 * Splices by index, so everything outside the blocks — including CSS between
 * two of them — is preserved byte for byte. Nothing is re-serialized.
 *
 * @param css    The stylesheet to clean.
 * @param blocks Blocks from `findLegacyBlocks` for this same stylesheet.
 * @return The stylesheet without those ranges.
 */
export function removeLegacyBlocks(
	css: string,
	blocks: LegacyBlock[]
): string {
	if ( ! blocks.length ) {
		return css;
	}

	let result = '';
	let cursor = 0;

	for ( const block of blocks ) {
		result += css.slice( cursor, block.start );
		cursor = Math.max( cursor, block.end );
	}

	return result + css.slice( cursor );
}

/**
 * Read the CSS string out of a `styles.css` value.
 *
 * WP stores this either as a bare string or as a `{ css: string }` object.
 * Returns `null` for anything else, which callers treat exactly like "no
 * blocks found" — we never inspect or rewrite a shape we don't recognise.
 *
 * @param value A `styles.css` value.
 * @return The CSS string, or null if the shape is unrecognised.
 */
export function readCustomCss( value: unknown ): string | null {
	if ( typeof value === 'string' ) {
		return value;
	}

	if ( isRecord( value ) && typeof value.css === 'string' ) {
		return value.css;
	}

	return null;
}

/**
 * Put a CSS string back into a `styles.css` value, preserving its shape.
 *
 * An object-shaped value stays an object so we never normalise something we
 * weren't asked to change.
 *
 * @param original The original `styles.css` value.
 * @param css      The replacement CSS string.
 * @return A value of the same shape as `original`.
 */
export function writeCustomCss( original: unknown, css: string ): unknown {
	if ( isRecord( original ) && typeof original.css === 'string' ) {
		return { ...original, css };
	}

	return css;
}

/**
 * Drop the `css` key from a styles object, for when nothing is left after
 * removal.
 *
 * @param styles A theme.json `styles` object.
 * @return A copy without `css`.
 */
export function omitCustomCss(
	styles: Record< string, unknown >
): Record< string, unknown > {
	const { css: _css, ...rest } = styles;
	return rest;
}

/**
 * Convenience wrapper: find the legacy blocks in a raw `styles.css` value of
 * either supported shape.
 *
 * @param value A `styles.css` value.
 * @return Blocks found, or an empty array for an unrecognised shape.
 */
export function findLegacyBlocksInStylesValue( value: unknown ): LegacyBlock[] {
	const css = readCustomCss( value );
	return css === null ? [] : findLegacyBlocks( css );
}
