/**
 * WordPress dependencies
 */
import { Button, Modal } from '@wordpress/components';
import { useSelect } from '@wordpress/data';
import { __, _n } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import useStyles from '@hooks/use-styles';
import { recordTracksEvent } from '@utils/tracks';
import './style.scss';

/**
 * Deep-link to the Additional CSS panel in the core Site Editor. The site
 * editor route reads `section` off the query string and passes it through as
 * the global-styles path, and `/css` is that panel.
 *
 * @return {string} URL of the Additional CSS panel.
 */
function getSiteEditorCssUrl() {
	return '/wp-admin/site-editor.php?p=%2Fstyles&section=%2Fcss';
}

/**
 * Warn that custom CSS saved by an older version of the Easy Site Editor may be
 * overriding the font or colour the user just picked.
 *
 * The full text of every block is shown so the user can check it doesn't
 * contain CSS they wrote themselves before agreeing to remove it — that
 * inspection is what makes removal safe to offer. "Edit myself" leads, so the
 * default path is the one where we touch nothing.
 *
 * @return {JSX.Element|null} The dialog, or null when there is nothing to report.
 */
export default function LegacyCssDialog() {
	const blocks = useSelect(
		( select ) => select( aiStore ).getLegacyCssBlocks(),
		[]
	);
	const { removeLegacyCss, dismissLegacyCssNotice } = useStyles();

	if ( ! blocks?.length ) {
		return null;
	}

	return (
		<Modal
			className="big-sky__legacy-css-dialog"
			title={ __( 'Older styles may be hiding your change', 'big-sky' ) }
			onRequestClose={ dismissLegacyCssNotice }
		>
			<p>
				{ _n(
					'An earlier version of the editor saved this to your Additional CSS. It can override the fonts you pick.',
					'An earlier version of the editor saved these to your Additional CSS. They can override the fonts you pick.',
					blocks.length,
					'big-sky'
				) }
			</p>

			<pre
				className="big-sky__legacy-css-dialog__preview"
				tabIndex={ 0 }
				role="region"
				aria-label={ __(
					'Custom CSS that would be removed',
					'big-sky'
				) }
			>
				{ blocks.map( ( block ) => block.text ).join( '\n\n' ) }
			</pre>

			<p className="big-sky__legacy-css-dialog__hint">
				{ __(
					'Check this does not include any CSS you wrote yourself. If not, it is safe to remove it.',
					'big-sky'
				) }
			</p>

			{ /* No explicit dismiss button — Modal renders a close control in
			     its header, and nothing here is destructive until Remove is
			     pressed. */ }
			<div className="big-sky__legacy-css-dialog__buttons">
				<Button
					variant="secondary"
					href={ getSiteEditorCssUrl() }
					target="_blank"
					rel="noreferrer"
					onClick={ () =>
						recordTracksEvent( 'legacy_css_edit_myself_click', {
							block_count: blocks.length,
						} )
					}
				>
					{ __( 'Edit myself', 'big-sky' ) }
				</Button>
				<Button
					variant="primary"
					onClick={ () => {
						recordTracksEvent( 'legacy_css_remove_click', {
							block_count: blocks.length,
						} );
						removeLegacyCss();
					} }
				>
					{ _n(
						'Remove this style',
						'Remove these styles',
						blocks.length,
						'big-sky'
					) }
				</Button>
			</div>
		</Modal>
	);
}
