/**
 * DOM utility functions for working with WordPress blocks.
 */

/**
 * Internal dependencies
 */
import { getCanvasIframeElements } from '@utils/canvas-iframe-elements';

/**
 * Scrolls to a specific block in the editor
 * @param {string}  blockClientId          - The client ID of the block to scroll to
 * @param {string}  position               - Scroll position ('start', 'center', 'end', 'nearest')
 * @param {boolean} selectBlockAfterScroll - Whether to select the block after scrolling (requires callbacks parameter)
 * @param {number}  offset                 - Offset in pixels for scroll margin
 * @param {Object}  callbacks              - Optional callbacks object with selectBlock function
 * @return {Promise<void>}
 */
export const scrollToBlock = async (
	blockClientId,
	position = 'start',
	selectBlockAfterScroll = false,
	offset = 0,
	callbacks = {}
) => {
	if ( blockClientId ) {
		const { canvasiFrameWindow } = getCanvasIframeElements();
		if (
			canvasiFrameWindow &&
			canvasiFrameWindow.document &&
			canvasiFrameWindow.document.readyState === 'complete'
		) {
			// Access the element within the iframe content
			const iframeElement = canvasiFrameWindow.document.getElementById(
				`block-${ blockClientId }`
			);

			// Scroll to the element within the iframe content
			if ( iframeElement ) {
				iframeElement.style.scrollMarginTop = `${ offset }px`;

				iframeElement.scrollIntoView( {
					behavior: 'smooth',
					block: position,
				} );
			}

			if ( selectBlockAfterScroll && callbacks.selectBlock ) {
				// Simple viewport check and selection
				const selectIfInViewport = () => {
					const boundingRect = iframeElement.getBoundingClientRect();
					let top = boundingRect.top;
					let bottom = boundingRect.bottom;

					if (
						boundingRect.height > canvasiFrameWindow.innerHeight
					) {
						top =
							boundingRect.top +
							( boundingRect.height -
								canvasiFrameWindow.innerHeight );
						bottom =
							boundingRect.bottom -
							( boundingRect.height -
								canvasiFrameWindow.innerHeight );
					}

					if (
						top >= 0 &&
						bottom <= canvasiFrameWindow.innerHeight
					) {
						callbacks.selectBlock( blockClientId );
						return true;
					}
					return false;
				};

				if ( selectIfInViewport() ) {
					return;
				}

				const handleScroll = () => {
					if ( selectIfInViewport() ) {
						canvasiFrameWindow.document.removeEventListener(
							'scroll',
							handleScroll
						);
					}
				};

				canvasiFrameWindow.document.addEventListener(
					'scroll',
					handleScroll
				);
			}
		}
	}
};

/**
 * Scrolls to the first block with a specific name
 * @param {string}   blockName       - The block name to search for
 * @param {string}   position        - Scroll position ('start', 'center', 'end', 'nearest')
 * @param {boolean}  select          - Whether to select the block after scrolling
 * @param {Function} getBlocksByName - Function to get blocks by name
 * @param {Object}   callbacks       - Optional callbacks object with selectBlock function
 * @return {void}
 */
export const scrollToFirstBlockByName = (
	blockName,
	position = 'start',
	select = false,
	getBlocksByName,
	callbacks = {}
) => {
	const blocks = getBlocksByName( blockName );
	if ( blocks.length > 0 ) {
		scrollToBlock( blocks[ 0 ], position, select, 0, callbacks );
	}
};
