/**
 * Internal dependencies
 */
import { getCanvasIframeElements } from '@utils/canvas-iframe-elements';
import setDelay from '@utils/set-delay';
import { select } from '@wordpress/data';
import { store as aiStore } from '@store';

/**
 * Block double-click event handler to prevent default behavior
 * @param {Event} e - The event object
 */
const blockDblclick = ( e ) => {
	e.preventDefault();
	e.stopImmediatePropagation();
};

/**
 * Zoom out the editor canvas
 * @param {Object}   dispatchers                         - Object containing dispatch functions
 * @param {Function} dispatchers.setZoomLevel            - Function to set zoom level
 * @param {Function} dispatchers.__unstableSetEditorMode - Function to set editor mode
 * @return {Promise} Promise that resolves when zoom out animation is complete
 */
export const zoomOut = async ( { setZoomLevel, __unstableSetEditorMode } ) => {
	const { canvasiFrameRoot } = getCanvasIframeElements();
	if ( setZoomLevel ) setZoomLevel( 0.5 );
	__unstableSetEditorMode( 'zoom-out' );

	// Add double-click event listener to prevent default behavior when building site
	const isBuildingSite = select( aiStore ).getIsBuildingSite();
	if ( isBuildingSite ) {
		const { canvasiFrameBody } = getCanvasIframeElements();
		if ( canvasiFrameBody ) {
			canvasiFrameBody.addEventListener(
				'dblclick',
				blockDblclick,
				true
			);
		}
	}

	// Wait for the next microtask to ensure the animations are registered
	await Promise.resolve();

	if ( canvasiFrameRoot ) {
		await Promise.all(
			canvasiFrameRoot
				.getAnimations()
				.map( ( animation ) => animation.finished )
		);
	}

	window.dispatchEvent( new Event( 'resize' ) );
	// Wait for the next event loop to make sure the `.zoom-out-animation` class is removed
	// (That Gutenberg class prevents us from scrolling to the new block)
	return await setDelay( 0 );
};

/**
 * Zoom in the editor canvas
 * @param {Object}   dispatchers                         - Object containing dispatch functions
 * @param {Function} dispatchers.resetZoomLevel          - Function to reset zoom level
 * @param {Function} dispatchers.__unstableSetEditorMode - Function to set editor mode
 * @return {Promise} Promise that resolves when zoom in animation is complete
 */
export const zoomIn = async ( { resetZoomLevel, __unstableSetEditorMode } ) => {
	const { canvasiFrameRoot } = getCanvasIframeElements();
	if ( resetZoomLevel ) resetZoomLevel();
	__unstableSetEditorMode( 'edit' );

	await Promise.resolve();

	if ( canvasiFrameRoot ) {
		await Promise.all(
			canvasiFrameRoot
				.getAnimations()
				.map( ( animation ) => animation.finished )
		);
	}

	window.dispatchEvent( new Event( 'resize' ) );
	// Remove double-click event listener
	const { canvasiFrameBody } = getCanvasIframeElements();
	if ( canvasiFrameBody ) {
		canvasiFrameBody.removeEventListener( 'dblclick', blockDblclick, true );
	}
	return await setDelay( 0 );
};
