/**
 * External dependencies
 */
import createSelector from 'rememo';
/**
 * WordPress dependencies
 */
import { createReduxStore, register } from '@wordpress/data';

/**
 * Internal dependencies
 */
import { STORE_NAME } from './constants.js';
import { generateImage } from './actions/openai.js';
import { getCustomAction } from './custom-actions.js';

import { runAgent } from './actions/agentic.js';
import { runSiteBuildAgent } from './actions/site-build.js';
import { reducer } from './reducer.js';
import debugLog from '@utils/log-debug';
import log from '@utils/log-debug.js';
import apiFetch from '@wordpress/api-fetch';
import uuidv4 from '@utils/uuid.js';
import { initializeSessionId } from '@utils/session-id.js';

const addMessage = ( message ) => {
	const preparedMessage = {
		...message,
		id: message.id || uuidv4(),
		created_at: message.created_at || Date.now() / 1000,
	};

	// Calypso custom action: Call custom `addMessage` if registered
	getCustomAction( 'addMessage' )?.( preparedMessage );

	return {
		type: 'ADD_MESSAGE',
		message: preparedMessage,
	};
};

const assistantSay = ( content, additionalProps = {} ) => {
	return addMessage( {
		role: additionalProps.role || 'assistant',
		content: content ? [ { type: 'text', text: content } ] : '',
		...additionalProps,
	} );
};

const actions = {
	addMessage,
	assistantSay,
	generateImage,
	runAgent,
	runSiteBuildAgent,
	setSessionLogged( isLogged ) {
		return {
			type: 'SET_SESSION_LOGGED',
			payload: isLogged,
		};
	},
	setIsEditorReady( isEditorReady ) {
		return {
			type: 'SET_IS_EDITOR_READY',
			payload: isEditorReady,
		};
	},
	setIsEditorIframeLoaded( isEditorIframeLoaded ) {
		return {
			type: 'SET_IS_EDITOR_IFRAME_LOADED',
			payload: isEditorIframeLoaded,
		};
	},
	addCachedImage( image ) {
		return {
			type: 'ADD_CACHED_IMAGE',
			payload: image,
		};
	},
	resetCachedContent() {
		// eslint-disable-next-line no-undef
		localStorage.removeItem(
			`bigSkyCachedContent${ window.Jetpack_Editor_Initial_State?.wpcomBlogId }`
		);
		return {
			type: 'SET_CACHED_CONTENT',
			payload: {},
		};
	},
	setIsBuildingSite( isBuildingSite ) {
		getCustomAction( 'setIsBuildingSite' )?.( isBuildingSite );

		return {
			type: 'SET_IS_BUILDING_SITE',
			payload: isBuildingSite,
		};
	},
	setIsProcessingSpec( isProcessingSpec ) {
		return {
			type: 'SET_IS_PROCESSING_SPEC',
			payload: isProcessingSpec,
		};
	},
	setCurrentColor( currentColor ) {
		return {
			type: 'SET_CURRENT_COLOR',
			payload: currentColor,
		};
	},
	setInitializedCustomScheme( initializedCustomScheme ) {
		return {
			type: 'SET_INITIALIZED_CUSTOM_SCHEME',
			payload: initializedCustomScheme,
		};
	},
	pushGeneratedVariations( generatedVariations ) {
		return {
			type: 'PUSH_GENERATED_VARIATIONS',
			payload: generatedVariations,
		};
	},
	clearGeneratedVariations() {
		return {
			type: 'CLEAR_GENERATED_VARIATIONS',
		};
	},
	setCurrentFont( currentFont ) {
		return {
			type: 'SET_CURRENT_FONT',
			payload: currentFont,
		};
	},
	setCurrentButtonStyle( currentButtonStyle ) {
		return {
			type: 'SET_CURRENT_BUTTON_STYLE',
			payload: currentButtonStyle,
		};
	},
	setImageStyle( imageStyle ) {
		return {
			type: 'SET_IMAGE_STYLE',
			payload: imageStyle,
		};
	},
	setSiteMetadata( siteMetadata ) {
		return {
			type: 'SET_SITE_METADATA',
			payload: siteMetadata,
		};
	},
	resetStore() {
		return {
			type: 'RESET_STORE',
		};
	},
	setCurrentPaletteColors( currentPaletteColors ) {
		return {
			type: 'SET_CURRENT_PALETTE_COLORS',
			payload: currentPaletteColors,
		};
	},
	setLegacyCssBlocks( legacyCssBlocks ) {
		return {
			type: 'SET_LEGACY_CSS_BLOCKS',
			payload: legacyCssBlocks,
		};
	},
	addUserMessage:
		( content, image_urls = [] ) =>
		( { dispatch } ) => {
			return dispatch.addMessage( {
				role: 'user',
				id: uuidv4(),
				content: [
					{
						type: 'text',
						text: content,
					},
					...image_urls?.map( ( image_url ) => ( {
						type: 'image_url',
						image_url, //: 'data:image/jpeg;base64,$base64'
					} ) ),
				],
			} );
		},
	setThinking( isThinking ) {
		// Calypso custom action: Call custom `setIsThinking` if registered
		getCustomAction( 'setIsThinking' )?.( isThinking );

		return {
			type: 'SET_THINKING',
			payload: isThinking,
		};
	},
	setThinkingMessage( thinkingMessage ) {
		getCustomAction( 'setThinkingMessage' )?.( thinkingMessage );

		return {
			type: 'SET_THINKING_MESSAGE',
			payload: thinkingMessage,
		};
	},
	clearMessages() {
		// Calypso custom action: Call custom `clearMessages` if registered
		getCustomAction( 'clearMessages' )?.();

		return {
			type: 'CLEAR_MESSAGES',
		};
	},
	setError: ( error ) => {
		return {
			type: 'SET_ERROR',
			error,
		};
	},
	setBuildErrorDialog( { isOpen, message } ) {
		return {
			type: 'SET_BUILD_ERROR_DIALOG',
			payload: { isOpen, message },
		};
	},
	setHeaderSectionIsReady( isReady ) {
		return {
			type: 'SET_HEADER_SECTION_IS_READY',
			payload: isReady,
		};
	},
	setPendingPageImageProcessing( pages ) {
		return {
			type: 'SET_PENDING_PAGE_IMAGE_PROCESSING',
			payload: pages,
		};
	},
	clearPendingPageImageProcessing() {
		return {
			type: 'CLEAR_PENDING_PAGE_IMAGE_PROCESSING',
		};
	},
	setAiStep( aiStep, previousStep = null ) {
		return {
			type: 'SET_AI_STEP',
			payload: aiStep,
			previousStep,
		};
	},
	setImageGenModel( imageGenModel ) {
		return {
			type: 'SET_IMAGE_GEN_MODEL',
			payload: imageGenModel,
		};
	},
	setImageGenQuality( imageGenQuality ) {
		return {
			type: 'SET_IMAGE_GEN_QUALITY',
			payload: imageGenQuality,
		};
	},
	setLogoGenQuality( logoGenQuality ) {
		return {
			type: 'SET_LOGO_GEN_QUALITY',
			payload: logoGenQuality,
		};
	},
	setBigSkyPendingSpec( spec ) {
		return {
			type: 'SET_BIG_SKY_PENDING_SPEC',
			payload: spec,
		};
	},
	setMosaicEnabled( mosaicEnabled ) {
		return {
			type: 'SET_MOSAIC_ENABLED',
			payload: mosaicEnabled,
		};
	},
};

const getAdditionalContext = createSelector(
	( state ) => {
		const additionalContext = {};
		if ( state.bigSkyInitialState?.siteIntent ) {
			additionalContext.siteIntent = state.bigSkyInitialState.siteIntent;
		}
		if (
			state.bigSkyInitialState?.siteGoals &&
			state.bigSkyInitialState.siteGoals.length > 0
		) {
			additionalContext.siteGoals = state.bigSkyInitialState.siteGoals;
		}
		return additionalContext;
	},
	( state ) => [ state.bigSkyInitialState ]
);

const store = createReduxStore( STORE_NAME, {
	reducer,

	actions: {
		...actions,
		runAgent,
		runSiteBuildAgent,
	},

	selectors: {
		getAdditionalContext,
		getCustomVariationTemplates( state ) {
			return state.customVariationTemplates;
		},
		getImageGenModel( state ) {
			return state.imageGenModel;
		},
		getLogoGenModel( state ) {
			return state.logoGenModel;
		},
		shouldLogSessions( state ) {
			return state.logSessions;
		},
		getSessionId( state ) {
			// Calypso custom action: Call custom `getSessionId` if registered
			// Use the Calypso session ID if available
			const calypsoSessionId = getCustomAction( 'getSessionId' )?.();
			if ( calypsoSessionId ) {
				return calypsoSessionId;
			}

			return state.sessionId;
		},
		isSessionLogged( state ) {
			return state.sessionLogged;
		},
		getDelaySettings( state ) {
			return state.delaySettings;
		},
		getIsEditorReady( state ) {
			return state.isEditorReady;
		},
		getIsEditorIframeLoaded( state ) {
			return state.isEditorIframeLoaded;
		},
		getCachedContent( state ) {
			return state.cachedContent;
		},
		getIsDevMode( state ) {
			return !! state.bigSkyInitialState?.isDevMode;
		},
		getUserLocale( state ) {
			return state.bigSkyInitialState?.userLocale || 'en_US';
		},
		getIsBuildingSite( state ) {
			return state.isBuildingSite;
		},
		getIsProcessingSpec( state ) {
			return state.isProcessingSpec;
		},
		getInitializedCustomScheme( state ) {
			return state.initializedCustomScheme;
		},
		getGeneratedVariations( state ) {
			return state.generatedVariations;
		},
		getCurrentColor( state ) {
			return state.currentColor;
		},
		getCurrentFont( state ) {
			return state.currentFont;
		},
		getCurrentButtonStyle( state ) {
			return state.currentButtonStyle;
		},
		getImageStyle( state ) {
			return state.imageStyle;
		},
		getSiteMetadata( state ) {
			return state.siteMetadata;
		},
		getCurrentPaletteColors( state ) {
			return state.currentPaletteColors;
		},
		getLegacyCssBlocks( state ) {
			return state.legacyCssBlocks;
		},
		// Message-related selectors
		getMessages( state ) {
			return state.messages;
		},
		getIsThinking( state ) {
			return state.isThinking;
		},
		getThinkingMessage( state ) {
			return state.thinkingMessage;
		},
		getBuildErrorDialog: ( state ) => state.buildErrorDialog,
		getHeaderSectionIsReady( state ) {
			return state.headerSectionIsReady;
		},
		getPendingPageImageProcessing( state ) {
			return state.pendingPageImageProcessing;
		},
		getGoogleFonts( state ) {
			return state.googleFonts;
		},
		getAiStep( state ) {
			return state.currentAiStep;
		},
		getImageGenQuality( state ) {
			return state.imageGenQuality;
		},
		getLogoGenQuality( state ) {
			return state.logoGenQuality;
		},
		getBigSkyPendingSpec( state ) {
			return state.bigSkyPendingSpec;
		},
		getMosaicEnabled( state ) {
			return state.mosaicEnabled;
		},
	},

	resolvers: {
		/**
		 * Resolver for the getGoogleFonts selector.
		 * This will be called automatically when getGoogleFonts() is used but no data is available.
		 * The resolver fetches the data from the API and updates the store.
		 */
		getGoogleFonts() {
			return async ( { dispatch } ) => {
				try {
					// Use apiFetch to make the API request
					const response = await apiFetch( {
						path: '/wpcom/v2/big-sky/v1/google-fonts',
						method: 'GET',
					} );

					// Make sure we have a valid response
					if ( response ) {
						// Update the store with the fetched data
						dispatch( {
							type: 'SET_GOOGLE_FONTS_COLLECTION',
							payload: response,
						} );
						return response;
					}
				} catch ( error ) {
					log.error( 'Failed to fetch Google Fonts data', error );
					return {};
				}
			};
		},

		// This is implemented as a resolver now, so that it's fairly easy in the future to make this async and API-driven.
		// Theoretically this could also be read while initializing state.
		getCachedContent:
			() =>
			( { dispatch } ) => {
				let payload = {};
				// eslint-disable-next-line no-undef
				const content = localStorage.getItem(
					`bigSkyCachedContent${ window.Jetpack_Editor_Initial_State?.wpcomBlogId }`
				);
				if ( content ) {
					try {
						payload = JSON.parse( content );
					} catch ( e ) {
						debugLog.error( 'Failed to parse cached content', e );
					}
				}
				dispatch( {
					type: 'SET_CACHED_CONTENT',
					payload,
				} );
			},
		getCustomVariationTemplates: () => {
			return async ( { dispatch } ) => {
				const request = await apiFetch( {
					path: '/wpcom/v2/big-sky/v1/variation-templates/colors',
				} );
				dispatch( {
					type: 'SET_CUSTOM_VARIATION_TEMPLATES',
					payload: request,
				} );
			};
		},
	},
} );

// Initialize the session ID from the store's state
initializeSessionId( store );

register( store );

export { store, STORE_NAME };
