/**
 * WordPress dependencies
 */
import { useDispatch, useSelect } from '@wordpress/data';
import { store as coreStore } from '@wordpress/core-data';
import { store as editorStore } from '@wordpress/editor';
import { useCallback } from '@wordpress/element';

/**
 * Internal dependencies
 */
import { unlock } from '@utils/lock-unlock';
import usePages from '@hooks/use-pages';
import { isValidStoreSite } from '@utils/store-site';

export default function useTemplates() {
	const HERO_TEMPLATE_SLUG = 'template-page-w-hero';

	const templates = useSelect( ( select ) => {
		return select( coreStore ).getEntityRecords(
			'postType',
			'wp_template',
			{
				per_page: -1,
			}
		);
	}, [] );
	const { getEntityRecord } = useSelect( coreStore );
	const { saveEntityRecord } = useDispatch( coreStore );
	const { homePageId } = usePages();
	const { revertTemplate } = unlock( useDispatch( editorStore ) );

	const getHeroTemplate = useCallback( () => {
		return templates?.find(
			( template ) => template.slug === HERO_TEMPLATE_SLUG
		);
	}, [ templates ] );

	const changeHomePageTemplate = useCallback(
		async ( setToDefault = false ) => {
			let templateSlug = '';
			if ( ! setToDefault && ! isValidStoreSite() ) {
				templateSlug = getHeroTemplate() ? HERO_TEMPLATE_SLUG : ''; // '' defaults to default template
			}

			// Get the current page data
			const currentPage = getEntityRecord(
				'postType',
				'page',
				homePageId
			);

			// Save the changes while preserving existing data
			await saveEntityRecord( 'postType', 'page', {
				...currentPage,
				template: templateSlug,
			} );
		},
		[ getEntityRecord, homePageId, saveEntityRecord, getHeroTemplate ]
	);

	const resetTemplates = useCallback( () => {
		if ( templates?.length ) {
			templates.forEach( ( template ) => {
				if ( template.modified ) {
					revertTemplate( template );
				}
			} );
		}
	}, [ templates, revertTemplate ] );

	return {
		HERO_TEMPLATE_SLUG,
		resetTemplates,
		getHeroTemplate,
		changeHomePageTemplate,
	};
}
