/**
 * WordPress dependencies
 */
import { select } from '@wordpress/data';

/**
 * Internal dependencies
 */
import { STORE_NAME } from '@store/constants.js';

/**
 * Check if the site is a valid store site.
 *
 * @return {boolean} True if the site is a valid store site.
 */

export function isValidStoreSite() {
	// WooCommerce is active and the site type is store
	const isWooCommerceActive = Boolean(
		window.bigSkyInitialState?.woocommerce
	);
	const siteType = select( STORE_NAME ).getSiteMetadata()?.siteType ?? null;
	return isWooCommerceActive && siteType === 'store';
}
