/**
 * WordPress dependencies
 */
import { requestJetpackToken } from '@utils/request-jetpack-token';
import withRetry from '@utils/retry';
import log from '@utils/log-debug';

/**
 * Fetches site spec data from the API with retry logic
 *
 * @param {string} specId - The spec ID to fetch
 * @return {Promise<Object>} The spec data
 * @throws {Error} If the request fails after all retries
 */
export const fetchSiteSpec = async ( specId ) => {
	const fetchSpec = async ( specIdParam ) => {
		log.info( `Fetching site spec: ${ specIdParam }` );

		const jetpackToken = await requestJetpackToken( true );
		if ( ! jetpackToken ) {
			throw new Error( 'No Jetpack token available' );
		}

		const response = await fetch(
			`https://public-api.wordpress.com/wpcom/v2/big-sky/site-spec/${ specIdParam }`,
			{
				method: 'GET',
				headers: {
					'Content-Type': 'application/json',
					Authorization: `X_JETPACK_JWT ${ jetpackToken.token }`,
				},
			}
		);

		if ( ! response.ok ) {
			throw new Error(
				`HTTP error! status: ${ response.status } - ${ response.statusText }`
			);
		}

		// Get the response as text and parse it into an object
		const responseText = await response.text();
		log.info( 'Spec API response received', {
			specId: specIdParam,
			responseLength: responseText.length,
		} );

		// Parse the JSON string - handle potential double encoding
		let specData = JSON.parse( responseText );
		if ( typeof specData === 'string' ) {
			specData = JSON.parse( specData );
		}

		return specData;
	};

	// Apply retry wrapper
	const retryWrapper = withRetry( fetchSpec, {
		maxRetries: 5,
		initialDelay: 1000,
		maxDelay: 8000,
	} );

	return await retryWrapper( specId );
};
