/**
 * Internal dependencies
 */
import log from '@utils/log-debug.js';
import logDebugThought from '@utils/log-debug-thought.js';
import { errorCodes, localToolRunningMessage } from '@utils/constants';
import { messageRoles } from '@utils/constants.js';
import { getCustomAction } from '../custom-actions.js';

/**
 * Default agent key used across agent actions
 */
const DEFAULT_AGENT_KEY = 'wp-orchestrator';

// How long a message sent before the chat is up waits for its agent.
const AGENT_WAIT_MS = 30000;
const AGENT_POLL_MS = 250;

/**
 * Agents Manager's agent manager, once it holds the agent. The chat loads Big
 * Sky's provider after the editor, so a message sent on arrival, like the
 * blueprint walkthrough's kickoff, can come before the agent exists.
 *
 * @param {string} agentKey Key of the agent the message goes to.
 * @return {Promise<Object|null>} The agent manager, or null if the agent never came.
 */
async function waitForAgentManager( agentKey ) {
	const deadline = Date.now() + AGENT_WAIT_MS;

	do {
		try {
			const agentManager = getCustomAction( 'getAgentManager' )?.();

			if ( agentManager?.hasAgent( agentKey ) ) {
				return agentManager;
			}
		} catch {
			// A manager that throws is not ready either.
		}

		await new Promise( ( resolve ) =>
			setTimeout( resolve, AGENT_POLL_MS )
		);
	} while ( Date.now() < deadline );

	return null;
}

/**
 * Store action to send a streaming message to the agenttic agent
 * This provides a way to send streaming messages from anywhere in the app without hooks
 * Handles the complete conversation flow internally - adds messages to store, manages thinking state, etc.
 *
 * @param {string}  message             - The message to send to the agent
 * @param {Object}  options             - Optional parameters for the message
 * @param {boolean} options.withHistory - Whether to include conversation history (default: true)
 * @param {string}  options.agentKey    - Key to identify the agent instance (default: 'wp-orchestrator')
 * @return {Function} Async thunk action that returns a promise
 */
export const runAgent =
	( message, options = {} ) =>
	async ( { select, dispatch } ) => {
		const {
			withHistory = false,
			agentKey = DEFAULT_AGENT_KEY,
			uploadedImages = [],
			hideUserMessage = false,
			...otherOptions
		} = options;

		// Agents Manager owns the agent, along with its context and session.
		const agentManager = await waitForAgentManager( agentKey );

		if ( ! agentManager ) {
			log.warn( 'runAgent: Agents Manager did not load the agent.' );
			return 'Agents Manager is not ready';
		}

		try {
			const messages = select.getMessages();

			let agentQuickActionMessage;

			// If there is only one message in the store and it is from the assistant
			// it must be a quick action message so we need to include it in the call
			// to the agent.
			if (
				messages.length === 1 &&
				messages[ 0 ]?.role === messageRoles.ASSISTANT &&
				messages[ 0 ]?.content[ 0 ]?.type === 'text'
			) {
				agentQuickActionMessage = messages[ 0 ]?.content[ 0 ]?.text;
			}

			// Prepare image URLs for addUserMessage (expects array of objects with url property)
			const imageUrlsForStore = uploadedImages.map( ( img ) => ( {
				url: img.url,
			} ) );

			// Prepare image URLs for agenttic-client (expects array of URL strings)
			const imageUrls = uploadedImages.map( ( img ) => img.url );

			// Add user message to store (with images if any).
			//
			// `hideUserMessage` sends the message to the agent without showing it
			// in the transcript, so a conversation the client opened on the
			// customer's behalf reads as the agent greeting them rather than as
			// something they appear to have typed themselves.
			if ( ! hideUserMessage ) {
				dispatch.addUserMessage( message, imageUrlsForStore );
			}

			// Set thinking state and add thinking message
			dispatch.setThinking( true );

			let finalResponse = '';
			let streamedText = '';

			const messageToSend = agentQuickActionMessage
				? `Agent question: ${ agentQuickActionMessage } \n\n User reply: ${ message }`
				: message;

			// Process streaming updates internally
			for await ( const update of agentManager.sendMessageStream(
				agentKey,
				messageToSend,
				{
					withHistory,
					...( imageUrls && imageUrls.length > 0
						? { imageUrls }
						: {} ),
					...otherOptions,
				}
			) ) {
				// Log any agent thoughts for debugging
				logDebugThought( update );

				// Check for progress updates in message parts
				const progressPart = update?.status?.message?.parts?.find(
					( part ) => part.type === 'progress'
				);
				if ( progressPart?.data?.summary ) {
					dispatch.setThinkingMessage( progressPart.data.summary );
				}

				// Track the reply as it arrives. Each update carries the answer
				// as it stands rather than just the newest fragment, so the
				// latest one always supersedes the last.
				if ( update?.text ) {
					if ( update.text !== localToolRunningMessage ) {
						streamedText = update.text;
					}

					if ( update.final ) {
						finalResponse = update.text;
						break;
					}
				}
			}

			// Clear thinking state and message
			dispatch.setThinking( false );
			dispatch.setThinkingMessage( '' );

			// Added once, at the end, rather than written to as the stream
			// arrives: the chat renders messages when they are added and ignores
			// later edits to their content, so a message posted mid-stream keeps
			// whatever text it was created with. That is what stranded customers
			// on the opening word of an answer the agent had finished sending.
			//
			// Falls back to the streamed text when the stream ends without a
			// final update, or when the final update is the local tool-running
			// marker rather than an answer — in both cases the reply the agent
			// did send would otherwise be dropped.
			const replyText =
				finalResponse && finalResponse !== localToolRunningMessage
					? finalResponse
					: streamedText;
			if ( replyText ) {
				dispatch.assistantSay( replyText );
			}

			return finalResponse || 'Response received';
		} catch ( error ) {
			const isUserCancellation = error.name === 'AbortError';
			// Clear thinking state and message on error
			dispatch.setThinking( false );
			dispatch.setThinkingMessage( '' );

			if ( error.message === errorCodes.QUOTA_EXCEEDED ) {
				log.warn( 'AI request quota exceeded' );
			} else if ( isUserCancellation ) {
				// not an error, just a user cancellation
				return 'Request aborted';
			} else {
				log.error( 'Error in runAgent:', error );
			}

			dispatch.setError( 'Agenttic error: ' + error.message );

			// Display error message in chat for user
			// Strip "Streaming error: " prefix if present
			const errorMessage = error.message.replace(
				/^Streaming error: /,
				''
			);
			dispatch.assistantSay( errorMessage );

			// Don't throw - error is already displayed to user
			// Return error message instead to avoid unhandled promise rejection
			return error.message;
		}
	};
