import { getSiteMetadataFields } from '@ai/assistants/constants';
import { defaultSiteMetadata } from '@utils/constants';
import log from '@utils/log-debug';

/**
 * Validates and processes raw spec data
 * @param {Object} rawSpecData - Raw spec data from API
 * @return {Object} Validated spec data ready for use
 * @throws {Error} If validation fails
 */
export const validateSpecData = ( rawSpecData ) => {
	// Get required site meta data keys
	const requiredFields = getSiteMetadataFields( 'required' );

	const missingFields = requiredFields.filter(
		( field ) => ! rawSpecData[ field ]
	);

	if ( missingFields.length > 0 ) {
		const error = new Error(
			`Missing required fields: ${ missingFields.join( ', ' ) }`
		);
		error.missingFields = missingFields;
		throw error;
	}

	// Filter specData to contain all valid site meta data fields
	const validSpecData = getSiteMetadataFields( 'all' ).reduce(
		( acc, key ) => {
			if ( rawSpecData[ key ] !== undefined ) {
				acc[ key ] = rawSpecData[ key ];
			}
			return acc;
		},
		{}
	);

	// Use the filtered spec data with defaults
	const validatedSpecData = {
		...defaultSiteMetadata,
		...validSpecData,
	};

	log.info( 'Spec data validated successfully', {
		specFields: Object.keys( validSpecData ),
		requiredFields,
	} );

	return validatedSpecData;
};
