export const TemplatePartSlug = Object.freeze( {
	Header: 'header',
	HeaderHero: 'header-hero',
	Footer: 'footer',
} );

export const TemplatePartPatternSlug = Object.freeze( {
	Header: 'header',
	HeaderHero: 'hero',
	Footer: 'footer',
} );

export const TemplatePartNames = Object.freeze( {
	[ TemplatePartSlug.Header ]: 'Header',
	[ TemplatePartSlug.Footer ]: 'Footer',
	[ TemplatePartSlug.HeaderHero ]: 'Hero',
	[ TemplatePartPatternSlug.HeaderHero ]: 'Hero',
} );

export const templatePartSlugs = Object.values( TemplatePartSlug );
export const templatePartPatternSlugs = Object.values(
	TemplatePartPatternSlug
);

export const isTemplatePartSlug = ( slug ) => {
	return templatePartSlugs.includes( slug );
};

export const isHeaderTemplatePartSlug = ( slug ) => {
	return (
		slug === TemplatePartSlug.Header || slug === TemplatePartSlug.HeaderHero
	);
};

export const isFooterTemplatePartSlug = ( slug ) => {
	return slug === TemplatePartSlug.Footer;
};

export const isTemplatePartPatternSlug = ( slug ) => {
	return templatePartPatternSlugs.includes( slug );
};

export const isHeaderTemplatePartPatternSlug = ( slug ) => {
	return (
		slug === TemplatePartPatternSlug.Header ||
		slug === TemplatePartPatternSlug.HeaderHero
	);
};

export const isFooterTemplatePartPatternSlug = ( slug ) => {
	return slug === TemplatePartPatternSlug.Footer;
};

export const getPatternSlugByTemplatePartName = ( templatePartName ) => {
	switch ( templatePartName ) {
		case TemplatePartSlug.Header:
			return TemplatePartPatternSlug.Header;
		case TemplatePartSlug.HeaderHero:
			return TemplatePartPatternSlug.HeaderHero;
		case TemplatePartSlug.Footer:
			return TemplatePartPatternSlug.Footer;
		default:
			return templatePartName;
	}
};

export const getTemplatePartNameByPatternSlug = ( patternSlug ) => {
	switch ( patternSlug ) {
		case TemplatePartPatternSlug.Header:
			return TemplatePartSlug.Header;
		case TemplatePartPatternSlug.HeaderHero:
			return TemplatePartSlug.HeaderHero;
		case TemplatePartPatternSlug.Footer:
			return TemplatePartSlug.Footer;
		default:
			return patternSlug;
	}
};

export const getTemplatePartName = ( slug ) => {
	return TemplatePartNames[ slug ] || TemplatePartPatternSlug[ slug ] || slug;
};
