/**
 * WordPress dependencies
 */
import { useDispatch, useSelect } from '@wordpress/data';
import { useCallback, useEffect, useRef } from '@wordpress/element';
import { __unstableAnimatePresence as AnimatePresence } from '@wordpress/components';
import { __ } from '@wordpress/i18n';
/**
 * Internal dependencies
 */
import AIBuildMode from '@components/ai-build-mode';
import AssemblerDebug from '@components/assembler-debug';
import ConfirmationDialog from '@components/confirmation-dialog';
import LegacyCssDialog from '@components/legacy-css-dialog';
import useAfterSave from '@hooks/use-after-save';
import useBuildSite from '@hooks/use-build-site';
import useLog from '@hooks/use-log';
import useResetSite from '@hooks/use-reset-site';
import { messageRoles } from '@utils/constants';
import { store as aiStore } from '@store';
import EditorSetup from '@components/editor-setup';
import Onboarding from '@components/onboarding';
import useShowSiteSpec from '@hooks/use-show-site-spec';
import useSiteBuildTrigger from '@hooks/use-site-build-trigger';
import useBlueprintWalkthroughKickoff from '@hooks/use-blueprint-walkthrough-kickoff';

import useCurrentScreen from '@hooks/use-current-screen';
import { Mosaic } from '@components/mosaic';
import { recordTracksEvent } from '@utils/tracks';

/**
 * This component wraps the Assembler component so that:
 * 1. It only renders on page post types
 * 2. It only renders after the canvas has loaded
 * 3. It logs the save action
 */
function BigSky() {
	const {
		isBuildingSite,
		isDevMode,
		isProcessingSpec,
		siteMetadata,
		headerSectionIsReady,
		messages,
		mosaicEnabled,
		buildErrorDialog,
	} = useSelect( ( select ) => {
		const storeSelect = select( aiStore );
		return {
			isBuildingSite: storeSelect.getIsBuildingSite(),
			isDevMode: storeSelect.getIsDevMode(),
			isProcessingSpec: storeSelect.getIsProcessingSpec(),
			siteMetadata: storeSelect.getSiteMetadata(),
			headerSectionIsReady: storeSelect.getHeaderSectionIsReady(),
			messages: storeSelect.getMessages(),
			mosaicEnabled: storeSelect.getMosaicEnabled(),
			buildErrorDialog: storeSelect.getBuildErrorDialog(),
		};
	}, [] );
	useSiteBuildTrigger();
	useBlueprintWalkthroughKickoff();

	const isAfterSave = useAfterSave();
	const { buildSite } = useBuildSite();
	const { logAction, logAssistantMessage } = useLog();
	const { buildNewSite } = useResetSite();

	const { setBuildErrorDialog } = useDispatch( aiStore );

	const { isSiteEditor, postType } = useCurrentScreen();
	const showSiteSpec = useShowSiteSpec();
	const passedSpec =
		new URLSearchParams( window.location.search ).get( 'spec_id' ) || '';
	const lastLoggedMessageRef = useRef( null );

	// Log the last assistant message.
	useEffect( () => {
		const lastMessage = messages?.[ messages?.length - 1 ];

		// Check if this message has already been logged
		if ( lastMessage && lastMessage !== lastLoggedMessageRef.current ) {
			const role = lastMessage?.role;
			const content =
				lastMessage?.content?.[ 0 ]?.text || lastMessage?.content || '';

			if ( role === messageRoles.ASSISTANT ) {
				logAssistantMessage( content, lastMessage.id );
			}

			// Update the ref with the last logged message
			lastLoggedMessageRef.current = lastMessage;
		}
	}, [ messages, logAssistantMessage ] );

	useEffect( () => {
		if ( isAfterSave ) {
			logAction( 'Page Saved', messageRoles.COMMENT );
		}
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [ isAfterSave ] );

	const handleBuildErrorRetry = useCallback( () => {
		recordTracksEvent( 'build_error_retry' );
		setBuildErrorDialog( { isOpen: false, message: null } );
		buildSite();
	}, [ setBuildErrorDialog, buildSite ] );

	const handleBuildErrorStartOver = useCallback( () => {
		recordTracksEvent( 'build_error_start_over' );
		setBuildErrorDialog( { isOpen: false, message: null } );
		buildNewSite();
	}, [ setBuildErrorDialog, buildNewSite ] );

	return (
		<>
			{ postType === 'page' && mosaicEnabled && (
				<Mosaic siteMetadata={ siteMetadata } />
			) }

			<AnimatePresence mode="wait">
				{ showSiteSpec &&
					! isBuildingSite &&
					! isProcessingSpec &&
					! passedSpec &&
					! headerSectionIsReady &&
					isSiteEditor && (
						<Onboarding
							key={ `onboarding-${ headerSectionIsReady }` }
						/>
					) }
			</AnimatePresence>

			{ isBuildingSite && <AIBuildMode /> }
			{ isDevMode ? <AssemblerDebug /> : null }
			<EditorSetup />

			<LegacyCssDialog />

			<ConfirmationDialog
				isOpen={ buildErrorDialog?.isOpen }
				onClose={ handleBuildErrorStartOver }
				onCancel={ handleBuildErrorStartOver }
				onConfirm={ handleBuildErrorRetry }
				cancelText={ __( 'Start over', 'big-sky' ) }
				confirmText={ __( 'Retry', 'big-sky' ) }
				messages={ [
					__(
						'Something went wrong while building your site.',
						'big-sky'
					),
				] }
				title={ __( 'Build Error', 'big-sky' ) }
			/>
		</>
	);
}

export default BigSky;
