/**
 * WordPress dependencies
 */
import apiFetch from '@wordpress/api-fetch';

/**
 * Internal dependencies
 */
import { getIsDevMode } from '@utils/env.js';
import { messageRoles } from '@utils/constants';
import { getCurrentScreenContext } from '@utils/env';

/**
 * Helper function to concatenate content with arguments
 *
 * @param {string} content   - The existing content
 * @param {string} arg       - The argument to add
 * @param {string} separator - The separator to use between content and arg
 * @return  {string}          The concatenated string
 */
export function addToPayload( content, arg, separator = ' ' ) {
	return content && content.length > 0 ? content + separator + arg : arg;
}

/**
 * Creates an action payload from error information
 *
 * @param {...*} args - Arguments to process into an error message
 * @return  {Array}    Array containing sessionId and error message object
 */
export function _actionFromError( ...args ) {
	return args.reduce(
		( payload, arg ) => {
			if ( typeof arg === 'string' ) {
				payload.content = addToPayload( payload.content, arg );
			} else if ( arg instanceof Error ) {
				payload.content = addToPayload(
					payload.content,
					`${ arg?.name }: ${ arg?.message }`
				);
				if ( arg?.stack ) {
					payload.trace = addToPayload( payload.trace, arg?.stack );
				}
			} else if ( arg instanceof Response ) {
				payload.content = addToPayload(
					payload.content,
					`Response: ${ arg?.url } ${ arg?.status } ${ arg?.statusText }`,
					`\n\n`
				);
			} else if ( typeof arg === 'object' && ! Array.isArray( arg ) ) {
				Object.entries( arg ).forEach( ( [ key, value ] ) => {
					try {
						if ( typeof value !== 'string' ) {
							value = JSON.stringify( value );
						}
						switch ( key ) {
							case 'content':
							case 'code':
								// Add code/content value to payload.content
								payload.content = addToPayload(
									payload.content,
									value
								);
								// Set non-'content' key on payload as below in `default`.
								if ( 'content' !== key ) {
									payload[ key ] = value;
								}
								break;
							default:
								// Set key on payload.
								payload[ key ] = value;
								break;
						}
					} catch ( e ) {
						// Do nothing
					}
				} );
			} else {
				try {
					payload.extra = addToPayload(
						payload.extra,
						JSON.stringify( arg )
					);
				} catch ( e ) {
					// Do nothing
				}
			}
			return payload;
		},
		{
			content: '',
			trace: '',
		}
	);
}

export default async function logAction(
	session_id,
	content,
	message_role = '',
	message_id = '',
	parent_message_id = '',
	attempt = 0
) {
	if ( ! session_id || content?.[ 0 ]?.type === messageRoles.COMPONENT ) {
		return;
	}

	// Break out if we're in a loop (third try)
	if ( attempt > 1 ) {
		console.error.call(
			window.console,
			'[LOOP!] Error logging action:',
			content
		);
		return;
	}

	const url = new URL( window.location.href );
	const phase = url?.searchParams?.get( 'ai-step' ) ?? 'editor';
	const editor = getCurrentScreenContext()?.screen;

	const data = {
		content,
		message_type: message_role,
		message_id,
		parent_message_id,
		is_test: getIsDevMode(),
		phase,
		editor,
		big_sky_version: window?.bigSkyInitialState?.bigSkyVersion ?? '0',
	};

	try {
		return await apiFetch( {
			path:
				'/wpcom/v2/big-sky/v1/session/' +
				encodeURIComponent( session_id ) +
				'/action',
			method: 'POST',
			data,
		} );
	} catch ( error ) {
		// Log with loop detection
		console.error.call(
			window.console,
			'[LOOP?] Error logging action:',
			error
		);

		// Try to log the error one more time with an incremented attempt count
		const errorMessage = _actionFromError(
			'Error logging action: ',
			error
		);
		if ( errorMessage ) {
			return logAction(
				session_id,
				errorMessage,
				message_role,
				message_id,
				parent_message_id,
				attempt + 1
			);
		}
	}
}
