/**
 * WordPress dependencies
 */
import { useDispatch, useRegistry, useSelect } from '@wordpress/data';
import { useCallback, useEffect } from '@wordpress/element';
import { store as coreStore } from '@wordpress/core-data';
import { privateApis as routerPrivateApis } from '@wordpress/router';
import { store as commandsStore } from '@wordpress/commands';
import { store as blockEditorStore } from '@wordpress/block-editor';

/**
 * Internal dependencies
 */
import useCurrentScreen from '@hooks/use-current-screen';
import { unlock } from '@utils/lock-unlock';
import log from '@utils/log-debug.js';
import { getCurrentScreenContext } from '@utils/env';
import { getBigSkyPages } from '@utils/pages';
import useNavigation from '@hooks/use-navigation';
const { useHistory } = unlock( routerPrivateApis );

export default function usePages() {
	const { homePageId } = useSelect(
		( select ) => ( {
			homePageId: select( coreStore ).getEntityRecord( 'root', 'site' )
				?.page_on_front,
		} ),
		[]
	);

	const currentScreenContext = getCurrentScreenContext();

	const registry = useRegistry();
	const { deleteEntityRecord, editEntityRecord, saveEditedEntityRecord } =
		useDispatch( coreStore );
	const { close } = useDispatch( commandsStore );
	const { postId: currentPostId, previousPostId } = useCurrentScreen();
	const { getBlocksByName } = useSelect( blockEditorStore );
	const { setBlockEditingMode } = useDispatch( blockEditorStore );
	const { renameGlobalNavigationById } = useNavigation();

	const deleteAllBigSkyPagesExceptHome = useCallback( async () => {
		const bigSkyPages = await getBigSkyPages();

		if ( ! bigSkyPages ) return;

		const deletePromises = bigSkyPages
			.filter(
				( page ) =>
					page.id !== homePageId && page.meta?.big_sky_generated
			) // Exclude home page and non-Big Sky generated pages
			.map( ( page ) =>
				deleteEntityRecord( 'postType', 'page', page.id, {
					force: true,
				} )
			);

		await Promise.all( deletePromises );
	}, [ homePageId, deleteEntityRecord ] );

	const history = useHistory();

	const goToHomePage = async () => {
		// Fetch homePageId and home URL asynchronously using proper data fetching patterns
		const siteRecord = await registry
			.resolveSelect( coreStore )
			.getEntityRecord( 'root', 'site' );

		const pageOnFront = siteRecord?.page_on_front;

		// Use page_on_front if it's valid, otherwise use root path (/)
		const path =
			pageOnFront && pageOnFront !== 0 ? `/page/${ pageOnFront }` : '/';

		goToPath( path );
	};

	const goToPath = async ( path ) => {
		// If we're already in the site editor, use history.push
		if ( currentScreenContext.screen === 'site-editor' ) {
			await history.navigate( path + '?canvas=edit' );
			// Ensure the mosaic view is closed. Perhaps we should deep link
			// this in the future.
			await close();
		} else {
			// If we're not in site editor, do a full navigation
			window.location.href = `/wp-admin/site-editor.php?p=${ encodeURIComponent(
				path
			) }&canvas=edit`;
		}
	};

	useEffect( () => {
		if ( ! previousPostId ) return;

		if ( currentPostId !== previousPostId ) {
			// In Gutenberg 20.6.0, the post content block has block editing mode disabled when switching pages
			// need to set block editing mode to default in order for blocks to be editable
			const postContentBlock = getBlocksByName( 'core/post-content' );
			setBlockEditingMode( postContentBlock?.[ 0 ]?.clientId, 'default' );
		}
	}, [
		currentPostId,
		previousPostId,
		getBlocksByName,
		setBlockEditingMode,
	] );

	const renamePage = useCallback(
		async ( pageId, newTitle, oldTitle, { save = false } = {} ) => {
			try {
				await editEntityRecord( 'postType', 'page', pageId, {
					title: newTitle,
				} );
				const updatedPage = save
					? await saveEditedEntityRecord( 'postType', 'page', pageId )
					: registry
							.select( coreStore )
							.getEditedEntityRecord(
								'postType',
								'page',
								pageId
							);

				const updatedNavigation = await renameGlobalNavigationById(
					pageId,
					newTitle,
					oldTitle
				);

				return {
					success: true,
					pageId,
					newTitle,
					updatedPage,
					updatedNavigation,
				};
			} catch ( error ) {
				log.error( 'Error renaming page:', error );
				return {
					success: false,
					error,
				};
			}
		},
		[
			editEntityRecord,
			saveEditedEntityRecord,
			registry,
			renameGlobalNavigationById,
		]
	);

	return {
		deleteAllBigSkyPagesExceptHome,
		goToHomePage,
		homePageId,
		renamePage,
	};
}
