/**
 * WordPress dependencies
 */
import { useCallback } from '@wordpress/element';

/**
 * Internal dependencies
 */
import log from '@utils/log-debug';
import useGeocoder from '@hooks/use-geocoder.js';
import useBuildSite from '@hooks/use-build-site.js';
import useSiteMetadata from '@hooks/use-site-metadata';

export default function useBuildSiteTool() {
	const { getCoordinates } = useGeocoder();
	const { getSiteMetadata, setSiteMetadata } = useSiteMetadata();
	const { buildSite } = useBuildSite();

	const buildSiteTask = useCallback(
		async ( parameters = null ) => {
			if ( ! parameters ) {
				parameters = getSiteMetadata();
			}
			log.info( 'TOOL CALLED: buildSite', parameters );

			// Note: In validateSpecData, unlisted fields are stripped out before this point.
			const siteMetadataToUpdate = {
				siteType: parameters.siteType,
				siteFeatures: parameters.siteFeatures,
				topic: parameters.topic,
				siteTitle: parameters.siteTitle,
				siteDescription: parameters.siteDescription,
				defaultImageStyle:
					parameters.imageStyle || parameters.defaultImageStyle,
				siteLocation: {
					name:
						parameters.siteLocationName ||
						parameters.siteLocation?.name,
				},
				requestedPages: parameters.requestedPages,
				personality: parameters.personality,
				requestedImages: parameters.requestedImages,
				siteGoals: parameters.siteGoals,
				keyFacts: parameters.keyFacts,
				primaryCallToAction: parameters.primaryCallToAction,
				avatarUrl: parameters.avatarUrl,
				avatarAltText: parameters.avatarAltText,
				avatarId: parameters.avatarId,
				siteEmail: parameters.siteEmail,
				sitePhone: parameters.sitePhone,
				siteLinks: parameters.siteLinks,
				_gravatar_flow: parameters._gravatar_flow,
			};
			if ( parameters.storeAddress ) {
				siteMetadataToUpdate.storeAddress = parameters.storeAddress;
			}
			if ( parameters.colorRequest ) {
				siteMetadataToUpdate.colorRequest = parameters.colorRequest;
			}
			if ( siteMetadataToUpdate.siteLocation.name ) {
				siteMetadataToUpdate.siteLocation.coordinates =
					await getCoordinates(
						siteMetadataToUpdate.siteLocation.name
					);
			}
			setSiteMetadata( siteMetadataToUpdate );

			buildSite();
		},
		[ buildSite, getSiteMetadata, setSiteMetadata, getCoordinates ]
	);

	return {
		buildSiteTask,
	};
}
