/**
 * Loads all button variations from the styles/buttons directory.
 *
 * @return {Array} Array of button variation objects.
 */
export function loadButtonVariations() {
	const context = import.meta.webpackContext( '../styles/buttons', {
		recursive: false,
		regExp: /\.json$/,
		mode: 'sync',
	} );

	const variations = [];
	for ( const key of context.keys() ) {
		try {
			variations.push( context( key ) );
		} catch ( error ) {
			console.error( `Error loading button variation ${ key }:`, error );
		}
	}
	return variations;
}
