import { useCallback, useEffect, useState } from '@wordpress/element';
import { subscribe, useDispatch, useSelect } from '@wordpress/data';
import { store as blockEditorStore } from '@wordpress/block-editor';

import useIsThinking from '@hooks/use-is-thinking';
import { store as aiStore } from '@store';
import { getMediaColor } from '@utils/images';
import { getCanvasIframeElements } from '@utils/canvas-iframe-elements';
import useBlocks from '@hooks/use-blocks';
import { isValidProcessingFeature } from '@utils/processing-features';

function EditorSubscriptions() {
	const [ isUpdatingCoverImage, setIsUpdatingCoverImage ] = useState( false );
	const [ coverBlockUrls, setCoverBlockUrls ] = useState( [] );
	const { getBlock, getBlocksByName, isEditorIframeLoaded, selectedBlock } =
		useSelect( ( select ) => {
			const { getSelectedBlock } = select( blockEditorStore );
			return {
				getBlock: select( blockEditorStore ).getBlock,
				getBlocksByName: select( blockEditorStore ).getBlocksByName,
				selectedBlock: getSelectedBlock(),
				isEditorIframeLoaded:
					select( aiStore ).getIsEditorIframeLoaded(),
			};
		} );
	const { getRootBlocks } = useBlocks();
	const { updateBlockAttributes } = useDispatch( blockEditorStore );
	const { isThinking } = useIsThinking();

	// Add subscription to restore processing states
	useEffect( () => {
		if ( ! isEditorIframeLoaded ) return;

		const unsubscribe = subscribe( () => {
			// don't need to do anything if
			if ( ! isThinking ) return;

			// Get all blocks in the editor
			const allBlocks = getRootBlocks();
			if ( ! allBlocks ) return;

			// Get the canvas iframe elements
			const { canvasiFrameWindow } = getCanvasIframeElements();
			if (
				! canvasiFrameWindow ||
				canvasiFrameWindow.document.readyState !== 'complete'
			)
				return;

			// Find all blocks with processing states
			const blocks = canvasiFrameWindow.document.querySelectorAll(
				'[data-big-sky-processing-state]'
			);
			blocks.forEach( ( block ) => {
				const state = block.dataset.bigSkyProcessingState;
				const features = block.dataset.bigSkyProcessingFeatures?.split(
					','
				) || [ 'all' ];

				if ( state === 'processing' ) {
					// Remove all processing-related classes first
					Array.from( block.classList ).forEach( ( className ) => {
						if (
							className.startsWith( 'big-sky__is-processing' ) ||
							className.startsWith( 'big-sky__has-processed' )
						) {
							block.classList.remove( className );
						}
					} );

					// Add appropriate processing classes based on features
					if ( features.includes( 'all' ) ) {
						block.classList.add( 'big-sky__is-processing' );
					} else {
						features.forEach( ( feature ) => {
							if (
								feature !== 'all' &&
								isValidProcessingFeature( feature )
							) {
								block.classList.add(
									`big-sky__is-processing-${ feature }`
								);
							}
						} );
					}
				} else if ( state === 'processed' ) {
					block.classList.add( 'big-sky__has-processed' );
				}
			} );
		} );

		return () => unsubscribe();
	}, [ isEditorIframeLoaded, isThinking, getRootBlocks ] );

	useEffect( () => {
		if ( ! isEditorIframeLoaded ) return;

		// get the cover block urls
		const coverBlockIds = getBlocksByName( 'core/cover' );
		setCoverBlockUrls(
			coverBlockIds.map( ( id ) => {
				const block = getBlock( id );
				return { clientId: block.clientId, url: block.attributes.url };
			} )
		);
	}, [ getBlock, getBlocksByName, isEditorIframeLoaded ] );

	const coverBlockUrlChanged = useCallback(
		( coverBlock ) => {
			const coverBlockId = coverBlock.clientId;
			// check if blockId exists in coverBlockUrls
			const coverBlockUrl = coverBlockUrls.find(
				( block ) => block.clientId === coverBlockId
			)?.url;
			return coverBlock.attributes.url !== coverBlockUrl;
		},
		[ coverBlockUrls ]
	);

	// if the selected block is a cover block and the url has changed, reset the custom overlay color
	const handleCoverBlockChange = useCallback( async () => {
		setIsUpdatingCoverImage( true );
		const mediaColor = await getMediaColor( selectedBlock.attributes.url );
		// get the cover block urls
		const coverBlockIds = getBlocksByName( 'core/cover' );
		setCoverBlockUrls(
			coverBlockIds.map( ( id ) => {
				const block = getBlock( id );
				return { clientId: block.clientId, url: block.attributes.url };
			} )
		);

		await updateBlockAttributes( selectedBlock.clientId, {
			overlayColor: undefined,
			customOverlayColor: mediaColor,
			isUserOverlayColor: false,
			dimRatio: 40,
		} );
		setIsUpdatingCoverImage( false );
	}, [ selectedBlock, updateBlockAttributes ] );

	useEffect( () => {
		if ( ! selectedBlock ) return;

		let unsubscribe = () => {};
		if (
			selectedBlock.name === 'core/cover' &&
			selectedBlock.attributes.url &&
			coverBlockUrlChanged( selectedBlock ) &&
			! isUpdatingCoverImage
		) {
			unsubscribe = subscribe( handleCoverBlockChange );
		}

		return () => {
			unsubscribe();
		};
	}, [
		selectedBlock,
		handleCoverBlockChange,
		coverBlockUrlChanged,
		isUpdatingCoverImage,
	] );

	return <></>;
}

export default EditorSubscriptions;
