/**
 * Internal dependencies
 */
import { isSimpleSite } from './site-type';

/**
 * WordPress dependencies
 */
import apiFetch from '@wordpress/api-fetch';

import log from '@utils/log-debug.js';

export const JWT_TOKEN_ID = 'jetpack-ai-jwt-token';
export const JWT_TOKEN_EXPIRATION_TIME = 30 * 60 * 1000;

declare global {
	interface Window {
		JP_CONNECTION_INITIAL_STATE: {
			apiNonce: string;
			siteSuffix: string;
			connectionStatus: { isActive: boolean };
		};
		Jetpack_Editor_Initial_State: {
			wpcomBlogId: string;
		};
	}
}

/**
 * Get the blog ID from localStorage or fallback to window object
 *
 * This function retrieves the blog ID using the following priority:
 * 1. From localStorage (cached token data from API response) - most reliable
 * 2. From window.Jetpack_Editor_Initial_State.wpcomBlogId - fallback
 * 3. null if neither is available
 *
 * @return {string | null} The blog ID or null if not available
 */
export function getBlogId(): string | null {
	try {
		const token = localStorage.getItem( JWT_TOKEN_ID );
		if ( token ) {
			const tokenData = JSON.parse( token );
			if ( tokenData?.blogId ) {
				return String( tokenData.blogId );
			}
		}
	} catch ( error ) {
		log.error( 'Failed to parse token data from localStorage:', error );
	}

	// Fallback to window object
	const windowBlogId = window.Jetpack_Editor_Initial_State?.wpcomBlogId;
	if ( windowBlogId ) {
		return String( windowBlogId );
	}

	return null;
}

/**
 * Request a token from the Jetpack site to use with the API
 *
 * This file is used to request a token from the Jetpack site to use with the API
 * This is a copy of https://github.com/woocommerce/woocommerce/blob/trunk/packages/js/ai/src/utils/requestJetpackToken.ts
 * Which is a copy of https://github.com/Automattic/jetpack/blob/2f10669cb673eb3e73b6f0001158e8ab62e4a6bc/projects/js-packages/ai-client/src/jwt/index.ts
 *
 * WooCommerce package cannot be used, because it was never published.
 * Jetpack package is published but its throwing errors if imported anywhere except in Jetpack.
 *
 * If you are going to copy this to your project, godspeed.
 *
 * @return {Promise<{token: string, blogId: string}>} The token and the blogId
 */

export async function requestJetpackToken( useCachedToken = true ) {
	const token = localStorage.getItem( JWT_TOKEN_ID );
	let tokenData;

	if ( token ) {
		tokenData = JSON.parse( token );
	}

	if (
		tokenData &&
		tokenData?.token &&
		tokenData?.expire &&
		tokenData?.expire > Date.now() &&
		useCachedToken
	) {
		// log.info( 'Using cached token', useCachedToken );
		return tokenData;
	}

	const apiNonce = window.JP_CONNECTION_INITIAL_STATE?.apiNonce;
	const siteId = window.Jetpack_Editor_Initial_State?.wpcomBlogId;

	let data = {
		token: '',
		blog_id: '',
	};

	try {
		if ( ! isSimpleSite() ) {
			data = await apiFetch( {
				path: '/jetpack/v4/jetpack-ai-jwt?_cacheBuster=' + Date.now(),
				credentials: 'same-origin',
				headers: {
					'X-WP-Nonce': apiNonce,
				},
				method: 'POST',
			} );
		} else {
			data = await apiFetch( {
				path: '/wpcom/v2/sites/' + siteId + '/jetpack-openai-query/jwt',
				method: 'POST',
			} );
		}
	} catch ( error ) {
		log.error( 'Failed to fetch Jetpack token:', error );
	}

	const newTokenData = {
		token: data.token,
		blogId: data.blog_id,

		/**
		 * Let's expire the token in 30 minutes
		 */
		expire: Date.now() + JWT_TOKEN_EXPIRATION_TIME,
	};

	log.info( 'Storing new token' );
	localStorage.setItem( JWT_TOKEN_ID, JSON.stringify( newTokenData ) );

	return newTokenData;
}
