/**
 * WordPress dependencies
 */

/**
 * Internal dependencies
 */
import logAction, { _actionFromError } from '@utils/log-action';
import { messageRoles } from '@utils/constants';
import { getSessionId } from '@utils/session-id';

const showLogs =
	( typeof window !== 'undefined' &&
		!! window?.bigSkyInitialState?.isDevMode ) ||
	false;
function storeLastPayload( payload ) {
	if ( ! showLogs ) {
		return;
	}
	window.bigSkyInitialState.lastPayload = payload;
}
const logger = {
	info: showLogs ? console.info.bind( window.console ) : () => {},
	warn: showLogs ? console.warn.bind( window.console ) : () => {},
	error( ...args ) {
		const sessionId = getSessionId();
		const errorMessage = _actionFromError( ...args );
		if ( errorMessage ) {
			logAction( sessionId, errorMessage, messageRoles.ERROR );
		}

		console.error.call( window.console, ...args );
	},
	storeLastPayload,
};

export default logger;
