/**
 * External dependencies
 */
import log from '@utils/log-debug';

/**
 * Creates a retry wrapper function that will retry the given function with exponential backoff.
 *
 * @param {Function} fn                          - The function to retry
 * @param {Object}   options                     - Retry options
 * @param {number}   [options.maxRetries=3]      - Maximum number of retry attempts
 * @param {number}   [options.initialDelay=1000] - Initial delay in milliseconds
 * @param {number}   [options.maxDelay=4000]     - Maximum delay in milliseconds
 * @return {Function} A function that will retry the original function when called
 */
const withRetry = (
	fn,
	{ maxRetries = 3, initialDelay = 1000, maxDelay = 4000 } = {}
) => {
	return async ( ...args ) => {
		let retryCount = 0;
		const functionName = fn.name || 'anonymous function';

		while ( retryCount < maxRetries ) {
			try {
				return await fn( ...args );
			} catch ( e ) {
				retryCount++;
				if ( retryCount >= maxRetries ) {
					log.error(
						`${ functionName } failed after all retries:`,
						e
					);
					return null;
				}

				// Exponential backoff with max delay
				const delay = Math.min(
					initialDelay * Math.pow( 2, retryCount - 1 ),
					maxDelay
				);
				log.info(
					`${ functionName } retry attempt ${ retryCount } after ${ delay }ms delay...`
				);
				await new Promise( ( resolve ) =>
					setTimeout( resolve, delay )
				);
			}
		}
	};
};

export default withRetry;
