import log from '@utils/log-debug';

/**
 * Removes a query parameter from the current URL without reloading page
 *
 * @param {string} paramName - The parameter name to remove
 */
export const removeUrlParam = ( paramName ) => {
	const newUrl = new URL( window.location );
	newUrl.searchParams.delete( paramName );
	window.history.replaceState( {}, '', newUrl );
	log.info( `URL parameter '${ paramName }' removed` );
};
