/**
 * WordPress dependencies
 */
import { Button, Modal } from '@wordpress/components';

export default function ConfirmationDialog( {
	isOpen,
	onClose,
	onCancel,
	onConfirm,
	cancelText,
	confirmText,
	messages,
	title,
	reverseButtons = false,
} ) {
	return (
		isOpen && (
			<Modal
				className="big-sky-onboarding__dialog"
				onRequestClose={ onClose }
				title={ title }
			>
				{ messages.map( ( message, index ) => (
					<p key={ index }>{ message }</p>
				) ) }
				<div className="big-sky-onboarding__dialog-buttons">
					{ ( reverseButtons ? confirmText : cancelText ) && (
						<Button
							variant="secondary"
							onClick={ reverseButtons ? onConfirm : onCancel }
						>
							{ reverseButtons ? confirmText : cancelText }
						</Button>
					) }
					{ ( reverseButtons ? cancelText : confirmText ) && (
						<Button
							variant="primary"
							onClick={ reverseButtons ? onCancel : onConfirm }
						>
							{ reverseButtons ? cancelText : confirmText }
						</Button>
					) }
				</div>
			</Modal>
		)
	);
}
