/**
 * Generates CSS for a @font-face rule.
 *
 * @param {Object} fontFace - The font face object with properties like src, fontWeight, fontStyle, etc.
 * @return {string} CSS string for the @font-face rule
 */
function generateFontFaceCSS( fontFace ) {
	const properties = Object.entries( fontFace )
		.map( ( [ key, value ] ) => {
			const kebabKey = key.replace(
				/[A-Z]/g,
				( m ) => `-${ m.toLowerCase() }`
			);

			if ( kebabKey === 'src' ) {
				if ( Array.isArray( value ) ) {
					const urls = value
						.map( ( url ) => `url("${ url }")` )
						.join( ', ' );
					return `  src: ${ urls };`;
				}
				return `  src: url("${ value }");`;
			}

			if ( kebabKey === 'font-family' ) {
				return `  ${ kebabKey }: "${ value }";`;
			}

			return `  ${ kebabKey }: ${ value };`;
		} )
		.join( '\n' );

	return `@font-face {\n${ properties }\n}`;
}

/**
 * Converts an array of font family objects to CSS.
 *
 * Resolves theme-bundled font `file:./assets/...` src values to a loadable URL
 * (e.g. `https://example.com/wp-content/themes/<stylesheet>/assets/...`).
 *
 * @param {Array} fontFamilies - Array of font family objects with fontFace property
 * @return {string} CSS string for the font families
 */
export function fontFamiliesToCSS( fontFamilies ) {
	let css = '';
	if ( Array.isArray( fontFamilies ) && fontFamilies.length > 0 ) {
		const themeBaseUrl = getActiveThemeBaseUrl();
		fontFamilies.forEach( ( fontFamily ) => {
			if ( fontFamily.fontFace ) {
				fontFamily.fontFace.forEach( ( fontFace ) => {
					if ( fontFace.src ) {
						const src = resolveFontFaceSrc(
							fontFace.src,
							themeBaseUrl
						);
						if ( ! src ) {
							return;
						}
						css += generateFontFaceCSS( {
							...fontFace,
							// Use 'block' to prevent flash during font loading.
							// The browser will briefly hide text while loading, then show it with the correct font.
							// This prevents the swap flash that occurs with 'swap' during re-renders.
							fontDisplay: fontFace.fontDisplay || 'block',
							src,
						} );
					}
				} );
			}
		} );
	}
	return css;
}

function resolveFontFaceSrc( src, themeBaseUrl ) {
	if ( typeof src === 'string' ) {
		const resolved = resolveFileSrcToThemeUrl( src, themeBaseUrl );
		return resolved.startsWith( 'file:' ) ? null : resolved;
	}
	if ( Array.isArray( src ) ) {
		const resolved = src
			.map( ( url ) => resolveFileSrcToThemeUrl( url, themeBaseUrl ) )
			.filter( ( url ) => url && ! url.startsWith( 'file:' ) );
		return resolved.length ? resolved : null;
	}
	return null;
}

function resolveFileSrcToThemeUrl( url, themeBaseUrl ) {
	if ( typeof url !== 'string' ) {
		return '';
	}
	if ( ! url.startsWith( 'file:' ) ) {
		return url;
	}

	if ( ! themeBaseUrl ) {
		return url;
	}

	let rel = url.replace( /^file:/, '' );
	rel = rel.replace( /^\.\//, '' );
	rel = rel.replace( /^\/+/, '' );

	const normalizedBase = themeBaseUrl.replace( /\/+$/, '' );
	return `${ normalizedBase }/${ rel }`;
}

function getActiveThemeBaseUrl() {
	// Prefer a theme-provided URI if available.
	try {
		const theme =
			window?.wp?.data?.select?.( 'core' )?.getCurrentTheme?.() || null;
		const stylesheetRaw = theme?.stylesheet;
		const stylesheetSlug =
			typeof stylesheetRaw === 'string' ? stylesheetRaw : '';
		const localBaseUrl =
			stylesheetSlug && window?.location?.origin
				? `${ window.location.origin }/wp-content/themes/${ stylesheetSlug }`
				: '';

		const rawUri =
			theme?.theme_uri ||
			theme?.themeUri ||
			theme?.stylesheet_uri ||
			theme?.stylesheetUri ||
			theme?.template_uri ||
			theme?.templateUri;

		const uri = normalizeThemeUri( rawUri );
		if ( uri ) {
			const baseFromUri = normalizeThemeBaseFromUri( uri );
			// Avoid cross-origin theme URLs (e.g. wordpress.com/themes/...) since they will
			// fail CORS when loading font files from a different origin.
			try {
				const baseOrigin = new URL( baseFromUri, window.location.href )
					.origin;
				if ( baseOrigin === window.location.origin ) {
					return baseFromUri;
				}
			} catch ( e ) {
				// ignore and fall back
			}
			// Prefer local same-origin base if available.
			if ( localBaseUrl ) {
				return localBaseUrl;
			}
			return baseFromUri;
		}

		if ( localBaseUrl ) {
			return localBaseUrl;
		}
	} catch ( e ) {
		// ignore
	}

	return '';
}

function normalizeThemeUri( value ) {
	if ( ! value ) {
		return '';
	}
	if ( typeof value === 'string' ) {
		return value;
	}
	// WP REST responses often return objects like { raw, rendered }.
	if ( typeof value === 'object' ) {
		const candidate =
			value.raw ||
			value.rendered ||
			value.href ||
			value.url ||
			value.link ||
			'';
		return typeof candidate === 'string' ? candidate : '';
	}
	return '';
}

function normalizeThemeBaseFromUri( uri ) {
	try {
		// If we were given a stylesheet URL, derive the theme directory URL.
		// Common shapes: https://.../wp-content/themes/<theme>/style.css
		const url = new URL( uri, window.location.href );
		let path = url.pathname || '';
		path = path.replace( /\/style(\.min)?\.css(\?.*)?$/i, '' );
		url.pathname = path;
		url.search = '';
		url.hash = '';
		return url.toString().replace( /\/+$/, '' );
	} catch ( e ) {
		return String( uri ).replace( /\/+$/, '' );
	}
}

/**
 * Injects CSS for font families into the editor iframe
 *
 * @param {Array} fontFamilies - Array of font family objects with fontFace property
 */
export function injectFontFamiliesIntoEditorIframe( fontFamilies ) {
	const css = fontFamiliesToCSS( fontFamilies );
	const editorIframe = document.querySelector(
		'iframe[name="editor-canvas"]'
	);
	if ( editorIframe && editorIframe.contentDocument ) {
		const style = document.createElement( 'style' );
		style.textContent = css;
		editorIframe.contentDocument.head.appendChild( style );
	}
}
