/**
 * WordPress dependencies
 */
import { usePrevious } from '@wordpress/compose';
import { useSelect } from '@wordpress/data';
import { store as editorStore } from '@wordpress/editor';
import { getCurrentScreenContext } from '@utils/env';

/**
 * Returns information about the current editor context
 *
 * @return {Object} Editor context information
 */
export default function useCurrentScreen() {
	const currentScreen = getCurrentScreenContext();
	const isSiteEditor = currentScreen?.screen === 'site-editor';
	const isPostEditor = currentScreen?.screen === 'post';
	const screen = currentScreen?.screen ?? '';
	const postType = useSelect( ( select ) =>
		select( editorStore ).getCurrentPostType()
	);

	const postId = useSelect( ( select ) =>
		select( editorStore ).getCurrentPostId()
	);
	const previousPostId = usePrevious( postId );
	const isPagePostType = postType === 'page';

	return {
		isSiteEditor,
		isPostEditor,
		screen,
		postType,
		isPagePostType,
		currentScreen,
		postId,
		previousPostId,
	};
}
