/**
 * WordPress dependencies
 */
import { store as blockEditorStore } from '@wordpress/block-editor';
import { dispatch, select } from '@wordpress/data';

/**
 * Internal dependencies
 */
import { getCanvasIframeElements } from '@utils/canvas-iframe-elements';
import log from '@utils/log-debug.js';

/**
 * Resets all block processing states by cleaning up both DOM and block attributes
 * This utility can be used from both React hooks and store actions
 *
 * Strategy:
 * 1. Finds all blocks with processing states via DOM queries (both by data attribute and class)
 * 2. Removes processing classes and data attributes from DOM elements
 * 3. Updates block attributes in the block editor store to prevent classes from reappearing on re-render
 *
 * @return {number} The number of blocks that were reset
 */
export function resetAllBlockProcessingStates() {
	try {
		const { canvasiFrameWindow } = getCanvasIframeElements();

		if ( ! canvasiFrameWindow ) {
			log.warning(
				'Cannot reset block processing states: canvas iframe not found'
			);
			return 0;
		}

		// Find all blocks with processing states (both by data attribute and by class)
		// This ensures we catch blocks that may have the class but not the data attribute
		const processingBlocksByAttr =
			canvasiFrameWindow.document.querySelectorAll(
				'[data-big-sky-processing-state="processing"]'
			);
		const processingBlocksByClass =
			canvasiFrameWindow.document.querySelectorAll(
				'[class*="big-sky__is-processing"]'
			);

		// Combine both sets to ensure we get all processing blocks
		const allProcessingBlocks = new Set( [
			...Array.from( processingBlocksByAttr ),
			...Array.from( processingBlocksByClass ),
		] );

		const { updateBlockAttributes } = dispatch( blockEditorStore );
		const { getBlock } = select( blockEditorStore );

		allProcessingBlocks.forEach( ( blockElement ) => {
			// Remove processing state data attributes
			delete blockElement.dataset.bigSkyProcessingState;
			delete blockElement.dataset.bigSkyProcessingFeatures;

			// Remove all processing-related classes from DOM
			Array.from( blockElement.classList ).forEach( ( className ) => {
				if (
					className.startsWith( 'big-sky__is-processing' ) ||
					className.startsWith( 'big-sky__has-processed' )
				) {
					blockElement.classList.remove( className );
				}
			} );

			// Also update the block attributes to remove processing classes
			// This prevents the classes from reappearing when the block is clicked/re-rendered
			const blockId = blockElement.getAttribute( 'data-block' );
			if ( blockId ) {
				const block = getBlock( blockId );
				if ( block?.attributes?.className ) {
					const cleanedClassName = block.attributes.className
						.split( ' ' )
						.filter(
							( className ) =>
								! className.startsWith(
									'big-sky__is-processing'
								) &&
								! className.startsWith(
									'big-sky__has-processed'
								)
						)
						.join( ' ' );

					updateBlockAttributes( blockId, {
						className: cleanedClassName,
					} );
				}
			}
		} );

		log.info(
			`Reset processing state for ${ allProcessingBlocks.size } blocks`
		);

		return allProcessingBlocks.size;
	} catch ( error ) {
		log.error( 'Error resetting block processing states:', error );
		return 0;
	}
}
