/**
 * WordPress dependencies
 */
import { store as blockEditorStore } from '@wordpress/block-editor';
import {
	subscribe,
	useDispatch,
	useRegistry,
	useSelect,
} from '@wordpress/data';
import { store as editorStore } from '@wordpress/editor';
import { store as preferencesStore } from '@wordpress/preferences';
import { useCallback, useEffect, useRef, useState } from '@wordpress/element';
import useCurrentScreen from '@hooks/use-current-screen';

/**
 * Internal dependencies
 */
import useBlocks from '@hooks/use-blocks';
import { store as aiStore } from '@store';
import setDelay from '@utils/set-delay';
import useCanvas from '@hooks/use-canvas.js';
import { getCanvasIframeElements } from '@utils/canvas-iframe-elements';
import useColorizedLogo from '@hooks/use-colorized-logo';
import useShowSiteSpec from '@hooks/use-show-site-spec';
import { unlock } from '@utils/lock-unlock';

export function SiteEditorSetup() {
	useCanvasSetup( { awaitEditor: true } );

	return null;
}

function PostEditorSetup() {
	useWaitPostEditorReady( { awaitEditor: true } );
	const editorMode = useSelect( ( select ) =>
		select( editorStore ).getEditorMode()
	);
	const { setIsEditorReady } = useDispatch( aiStore );

	useEffect( () => {
		if ( editorMode !== 'visual' ) {
			setIsEditorReady( false );
		}
	}, [ editorMode, setIsEditorReady ] );

	return null;
}

export default function EditorSetup() {
	const { isSiteEditor, isPostEditor } = useCurrentScreen();
	if ( isSiteEditor ) {
		return <SiteEditorSetup />;
	}

	if ( isPostEditor ) {
		return <PostEditorSetup />;
	}

	return null;
}

// This hook is deliberately in the same file as the component that uses it as the
// useEffects run should only be added once so we don't want this hook accidently used elsewhere.
function useCanvasSetup( { awaitEditor } ) {
	const { canvasMode, setIframeScale, zoomOut } = useCanvas();
	const [ awaitingEditor, setAwaitingEditor ] = useState( false );
	const { getBlockCount } = useSelect( blockEditorStore );
	const selectedBlockName = useSelect(
		( select ) => select( blockEditorStore ).getSelectedBlock()?.name,
		[]
	);
	const zoomLevel = useSelect(
		( select ) => unlock( select( blockEditorStore ) ).getZoomLevel(),
		[]
	);
	const { getEditorSettings } = useSelect( editorStore );
	const { updateEditorSettings } = useDispatch( editorStore );
	const { setDefaultRenderingMode, setRenderingMode } = unlock(
		useDispatch( editorStore )
	);

	const { isBuildingSite, isEditorReady, isEditorIframeLoaded } = useSelect(
		( select ) => ( {
			isBuildingSite: select( aiStore ).getIsBuildingSite(),
			isEditorReady: select( aiStore ).getIsEditorReady(),
			isEditorIframeLoaded: select( aiStore ).getIsEditorIframeLoaded(),
		} ),
		[]
	);
	const showSiteSpec = useShowSiteSpec();

	const { getRootBlocks } = useBlocks();

	const { setDefaults: setPreferencesDefaults } =
		useDispatch( preferencesStore );
	const { setIsEditorReady, setIsEditorIframeLoaded } =
		useDispatch( aiStore );

	const { setShowWelcomeGuide } =
		useDispatch( 'automattic/wpcom-welcome-guide' ) ?? {}; // eslint-disable-line @wordpress/data-no-store-string-literals

	useEffect( () => {
		const whenEditorIsReady = () => {
			return new Promise( ( resolve ) => {
				const unsubscribe = subscribe( () => {
					// This will trigger after the initial render blocking, before the window load event
					// This seems currently more reliable than using __unstableIsEditorReady
					if ( getRootBlocks()?.length >= 0 ) {
						unsubscribe();
						resolve();
					}
				} );
			} );
		};

		const waitForEditorReady = async () => {
			await whenEditorIsReady();
			setIsEditorReady( true );
		};

		if ( awaitEditor && ! awaitingEditor ) {
			setAwaitingEditor( true );
			waitForEditorReady();
		}
	}, [
		getBlockCount,
		setIsEditorReady,
		awaitEditor,
		awaitingEditor,
		getRootBlocks,
	] );

	const getCanvasHtml = useCallback( () => {
		const { canvasiFrameDocument } = getCanvasIframeElements();
		return canvasiFrameDocument?.querySelector( 'html' );
	}, [] );

	useEffect( () => {
		setPreferencesDefaults( 'core', {
			isComplementaryAreaVisible: false,
			showBlockBreadcrumbs: false,
		} );

		setPreferencesDefaults( 'core/edit-site', {
			isComplementaryAreaVisible: false,
			welcomeGuide: false,
			welcomeGuidePage: false,
			welcomeGuideStyles: false,
			welcomeGuideTemplate: false,
		} );
	}, [ setPreferencesDefaults ] );

	useEffect( () => {
		if ( setShowWelcomeGuide ) setShowWelcomeGuide( false );
	}, [ setShowWelcomeGuide ] );

	useEffect( () => {
		const checkIframeLoaded = async () => {
			const canvasHtml = getCanvasHtml();
			if (
				! canvasHtml?.classList.contains( 'block-editor-iframe__html' )
			) {
				await setDelay( 500 );
				checkIframeLoaded();
				return;
			}

			setIsEditorIframeLoaded( true );
		};
		if ( isEditorReady && awaitEditor && ! isEditorIframeLoaded ) {
			checkIframeLoaded();
		}
	}, [
		awaitEditor,
		getCanvasHtml,
		isEditorIframeLoaded,
		isEditorReady,
		setIsEditorIframeLoaded,
	] );

	useColorizedLogo();

	const observer = useRef( null );

	useEffect( () => {
		const { canvasiFrame } = getCanvasIframeElements();

		if ( isEditorIframeLoaded ) {
			// set iframe visibility
			if ( canvasiFrame ) {
				canvasiFrame.style.visibility = 'visible';
			}

			if ( ! observer.current ) {
				observer.current = new window.MutationObserver(
					( mutations ) => {
						for ( const mutation of mutations ) {
							for ( const removedNode of mutation.removedNodes ) {
								if ( removedNode.contains( canvasiFrame ) ) {
									setIsEditorIframeLoaded( false );
								}
							}
						}
					}
				);
				observer.current.observe(
					document.getElementById( 'site-editor' ),
					{ subtree: true, childList: true }
				);
			}
		} else if ( observer.current ) {
			observer.current.disconnect();
			observer.current = null;
		}

		return () => {
			if ( observer.current ) {
				observer.current.disconnect();
				observer.current = null;
			}
		};
	}, [ isEditorIframeLoaded, setIsEditorIframeLoaded ] );

	useEffect( () => {
		const adjustCanvasOpacity = async () => {
			const { canvasiFrame } = getCanvasIframeElements();
			if ( isEditorReady && ! isEditorIframeLoaded && canvasiFrame ) {
				canvasiFrame.style.opacity = 0;
			} else if (
				isEditorReady &&
				isEditorIframeLoaded &&
				canvasiFrame
			) {
				await setDelay( 300 );
				canvasiFrame.style.opacity = 1;
			}
		};
		adjustCanvasOpacity();
	}, [ isEditorReady, isEditorIframeLoaded ] );

	// We need to undo what Gutenberg core's DisableNonPageContentBlocks does.
	const registry = useRegistry();
	const idsToRestore = useSelect( ( select ) => {
		const { getBlockOrder, getBlocksByName, getBlockEditingMode } =
			select( blockEditorStore );
		const templatePartIds = getBlocksByName( 'core/template-part' );
		return [
			...templatePartIds.filter(
				( clientId ) =>
					getBlockEditingMode( clientId ) === 'contentOnly'
			),
			...templatePartIds
				.flatMap( ( clientId ) => getBlockOrder( clientId ) )
				.filter(
					( clientId ) =>
						getBlockEditingMode( clientId ) === 'disabled'
				),
		];
	}, [] );

	useEffect( () => {
		if ( idsToRestore?.length ) {
			for ( const id of idsToRestore ) {
				registry
					.dispatch( blockEditorStore )
					.setBlockEditingMode( id, 'default' );
			}
		}
	}, [ idsToRestore, registry ] );

	const setRenderingModeCompatible = useCallback(
		( renderingMode ) => {
			if ( typeof setDefaultRenderingMode === 'function' ) {
				setDefaultRenderingMode( renderingMode );
			} else {
				setRenderingMode( renderingMode );
			}
		},
		[ setRenderingMode, setDefaultRenderingMode ]
	);

	/**
	 * Initialize the build canvas when the site is being built.
	 *
	 * Zoom out and lock the template so the skeleton fills the frame. We must
	 * NOT clear the canvas here: buildSite() sets up the skeleton (blanked
	 * header/footer + placeholder body sections) as the build starts, and a
	 * delayed clear would race with and wipe those placeholders, leaving the
	 * canvas blank for the whole planning phase.
	 */
	useEffect( () => {
		if ( ! isBuildingSite ) return;

		zoomOut();
		setRenderingModeCompatible( 'template-locked' );
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [ isBuildingSite ] );

	const lastOnNavigateToEntityRecord = useRef( undefined );

	useEffect( () => {
		if ( ! selectedBlockName ) return;

		if ( selectedBlockName === 'core/template-part' ) {
			lastOnNavigateToEntityRecord.current =
				getEditorSettings().onNavigateToEntityRecord;
			updateEditorSettings( {
				onNavigateToEntityRecord: undefined,
			} );
		} else if ( lastOnNavigateToEntityRecord.current ) {
			updateEditorSettings( {
				onNavigateToEntityRecord: lastOnNavigateToEntityRecord.current,
			} );
		}
	}, [ selectedBlockName, updateEditorSettings, getEditorSettings ] );

	useEffect( () => {
		if ( ! isEditorIframeLoaded ) return;

		const { canvasiFrame, canvasiFrameRoot } = getCanvasIframeElements();

		if ( ! canvasiFrame ) return;

		const classNameMap = {
			'big-sky__is-building-site': isBuildingSite || showSiteSpec,
			'is-zoomed-out': zoomLevel < 1,
		};

		for ( const [ className, isActive ] of Object.entries(
			classNameMap
		) ) {
			canvasiFrame.classList.toggle( className, isActive );
			canvasiFrameRoot?.classList.toggle( className, isActive );
		}
	}, [ isEditorIframeLoaded, isBuildingSite, showSiteSpec, zoomLevel ] );

	// While a site build is in progress, hide the editor's settings sidebar
	// (and the top-toolbar editing tools) so the "Generating your site" moment
	// stays clean and page settings — status, trash, meta — can't be edited
	// mid-build. Body-scoped (unlike the canvas-iframe `big-sky__is-building-site`
	// class) because the settings sidebar is a sibling region of the canvas, not
	// inside it. Reverts automatically when the build finishes.
	useEffect( () => {
		const className = 'big-sky__hide-editor-chrome';
		document.body.classList.toggle( className, isBuildingSite );
		return () => {
			document.body.classList.remove( className );
		};
	}, [ isBuildingSite ] );

	useEffect( () => {
		const handleCanvasModeChange = async () => {
			const { canvasiFrameRoot } = getCanvasIframeElements();
			const messageList = document.querySelector(
				'.big-sky__ai-messages'
			);
			if ( canvasMode === 'view' ) {
				document
					.querySelector( 'body' )
					.classList.add( 'big-sky__canvas-mode-view' );
				canvasiFrameRoot?.classList?.add( 'big-sky__canvas-mode-view' );
				if ( messageList ) messageList.style.visibility = 'hidden';
			} else {
				document
					.querySelector( 'body' )
					.classList.remove( 'big-sky__canvas-mode-view' );
				canvasiFrameRoot?.classList?.remove(
					'big-sky__canvas-mode-view'
				);

				await setDelay( 1500 );
				if ( messageList ) messageList.style.visibility = 'visible';
				setIframeScale();
			}
		};

		handleCanvasModeChange();
	}, [ canvasMode, isEditorIframeLoaded, setIframeScale ] );
}

function useWaitPostEditorReady( { awaitEditor } ) {
	const [ awaitingEditor, setAwaitingEditor ] = useState( false );
	const { getBlockCount } = useSelect( ( select ) => ( {
		getBlocks: select( blockEditorStore ).getBlocks,
		getBlockCount: select( blockEditorStore ).getBlockCount,
	} ) );

	const editorMode = useSelect( ( select ) =>
		select( editorStore ).getEditorMode()
	);

	const { isSiteEditor } = useCurrentScreen();

	const { getRootBlocks } = useBlocks();

	const { setIsEditorReady } = useDispatch( aiStore );

	useEffect( () => {
		if ( editorMode !== 'visual' ) {
			setAwaitingEditor( false );
		}

		const whenEditorIsReady = () => {
			return new Promise( ( resolve ) => {
				const unsubscribe = subscribe( () => {
					const blockCount = getRootBlocks()?.length;

					const { canvasiFrameDocument } = getCanvasIframeElements();
					const iframeHtml =
						canvasiFrameDocument?.querySelector( 'html' );
					const isIframeReady =
						iframeHtml &&
						iframeHtml.classList.contains(
							'block-editor-iframe__html'
						);

					if ( blockCount > 0 && isIframeReady ) {
						unsubscribe();
						resolve();
					}
				} );
			} );
		};

		const waitForEditorReady = async () => {
			await whenEditorIsReady();
			setIsEditorReady( true );
		};

		if ( awaitEditor && ! awaitingEditor && editorMode === 'visual' ) {
			setAwaitingEditor( true );
			waitForEditorReady();
		}
	}, [
		getBlockCount,
		setIsEditorReady,
		awaitEditor,
		awaitingEditor,
		getRootBlocks,
		editorMode,
		isSiteEditor,
	] );
}
