/**
 * Internal dependencies
 */

/**
 * Get the session ID from the store.
 *
 * @return {string} The session ID.
 */
export function getSessionId() {
	return _sessionId;
}

/**
 * Initialize the session ID from the store's state.
 *
 * @param {Object} store - The Redux store instance
 */
export function initializeSessionId( store ) {
	const aiStore = store.instantiate().store;
	const state = aiStore.getState();
	_sessionId = state.sessionId;
}

// Private variable to store the session ID
let _sessionId = null;
