/**
 * Build a map of synthetic image IDs (id-*) to actual block clientIds.
 *
 * @param {Object} blockEditorSelect Block editor store selector.
 * @return {Map<string,string>} Mapping of synthetic IDs to clientIds.
 */
const buildSyntheticImageIdMap = ( blockEditorSelect ) => {
	const syntheticIdMap = new Map();
	const imageClientIds = [];

	if ( ! blockEditorSelect || ! blockEditorSelect.getBlocks ) {
		return {
			map: syntheticIdMap,
			imageClientIds,
		};
	}

	const flattenBlocks = ( blocks, accumulator = [] ) => {
		if ( ! Array.isArray( blocks ) || ! blocks.length ) {
			return accumulator;
		}

		blocks.forEach( ( block ) => {
			if ( ! block ) {
				return;
			}

			accumulator.push( block );

			let innerBlocks = block.innerBlocks;
			if (
				block.name === 'core/template-part' ||
				block.name === 'core/post-content'
			) {
				const templateBlocks = blockEditorSelect.getBlocks(
					block.clientId
				);
				if (
					Array.isArray( templateBlocks ) &&
					templateBlocks.length
				) {
					innerBlocks = templateBlocks;
				}
			}

			if ( innerBlocks && innerBlocks.length ) {
				flattenBlocks( innerBlocks, accumulator );
			}
		} );

		return accumulator;
	};

	const rootBlocks = blockEditorSelect.getBlocks();
	const allBlocks = flattenBlocks( rootBlocks );

	allBlocks.forEach( ( block ) => {
		if ( block.name !== 'core/image' && block.name !== 'core/cover' ) {
			return;
		}

		imageClientIds.push( block.clientId );

		const attributeId = block?.attributes?.id;
		const numericId = parseInt( attributeId, 10 );
		if ( Number.isNaN( numericId ) ) {
			return;
		}

		const syntheticKey = `id-${ numericId }`;
		if ( ! syntheticIdMap.has( syntheticKey ) ) {
			syntheticIdMap.set( syntheticKey, block.clientId );
		}
	} );

	return {
		map: syntheticIdMap,
		imageClientIds,
	};
};

/**
 * Determine whether the provided clientId uses the synthetic image id format.
 *
 * @param {string} clientId Candidate clientId from the workflow stream.
 * @return {boolean} True when the id matches the synthetic prefix.
 */
const isSyntheticImageClientId = ( clientId ) => {
	return typeof clientId === 'string' && clientId.startsWith( 'id-' );
};

/**
 * Attempt to map workflow-provided clientIds to actual block clientIds.
 *
 * @param {string} clientId               Workflow clientId.
 * @param {Object} reverseMap             Existing reverse mapping.
 * @param {Map}    syntheticImageMap      Map of synthetic ids to actual clientIds.
 * @param {Set}    missingNonSyntheticIds Collector for missing non-synthetic ids.
 * @param {Set}    missingSyntheticIds    Collector for missing synthetic ids.
 * @param {Array}  imageClientIds         Array of image client IDs.
 * @param {Set}    usedImageClientIds     Set of already used image client IDs.
 * @return {boolean} Whether the mapping was established.
 */
const ensureReverseMapEntry = (
	clientId,
	reverseMap,
	syntheticImageMap,
	missingNonSyntheticIds,
	missingSyntheticIds,
	imageClientIds,
	usedImageClientIds
) => {
	if ( ! clientId ) {
		return false;
	}

	if ( reverseMap[ clientId ] ) {
		usedImageClientIds.add( reverseMap[ clientId ] );
		return true;
	}

	if ( isSyntheticImageClientId( clientId ) ) {
		let mappedClientId = syntheticImageMap.get( clientId );

		if ( ! mappedClientId ) {
			mappedClientId = imageClientIds.find(
				( candidate ) =>
					candidate && ! usedImageClientIds.has( candidate )
			);

			if ( mappedClientId ) {
				syntheticImageMap.set( clientId, mappedClientId );
			}
		}

		if ( mappedClientId ) {
			reverseMap[ clientId ] = mappedClientId;
			usedImageClientIds.add( mappedClientId );
			return true;
		}

		missingSyntheticIds.add( clientId );
		console.warn(
			`⚠️ Unable to locate image block with synthetic id "${ clientId }".`
		);
		return false;
	}

	missingNonSyntheticIds.add( clientId );
	return false;
};

/**
 * Recursively recreates a block while adding processing class to image blocks.
 * Skips adding processing class to images within certain patterns (e.g., testimonials, team).
 *
 * @param {Object}  block      Block to recreate
 * @param {boolean} shouldSkip Whether to skip adding processing class to image blocks
 * @return {Object} Recreated block with image processing class if applicable
 */
const recreateBlockWithProcessingState = ( block, shouldSkip = false ) => {
	if ( ! block ) {
		return block;
	}

	// First recreate the block normally
	const recreatedBlock = recreateBlock( block );

	// Check if this block is a pattern that should skip processing classes
	// Currently: testimonials and team patterns skip image processing classes
	const isExcludedPattern = [ 'testimonials', 'team' ].includes(
		recreatedBlock.attributes?.metadata?.patternCategory
	);
	const skipProcessing = shouldSkip || isExcludedPattern;

	// If it's an image block or WooCommerce block, append the processing class
	// Skip if shouldSkip is true (e.g., within testimonial patterns)
	const isImageBlock =
		recreatedBlock.name === 'core/image' ||
		recreatedBlock.name === 'core/cover' ||
		recreatedBlock.name === 'core/site-logo';
	const isWooCommerceBlock =
		recreatedBlock.name === 'woocommerce/single-product' ||
		recreatedBlock.name === 'woocommerce/product-collection';

	if ( ! skipProcessing && ( isImageBlock || isWooCommerceBlock ) ) {
		let className = 'big-sky__is-processing-images';
		if ( recreatedBlock.name === 'core/cover' ) {
			className = 'big-sky__is-processing-background-images';
		} else if (
			recreatedBlock.name === 'core/site-logo' ||
			isWooCommerceBlock
		) {
			className = 'big-sky__is-processing';
		}

		const existingClassName = recreatedBlock.attributes?.className || '';
		recreatedBlock.attributes = {
			...recreatedBlock.attributes,
			className: existingClassName
				? `${ existingClassName } ${ className }`
				: className,
		};
	}

	// Recursively handle inner blocks, passing down the skip flag
	if (
		recreatedBlock.innerBlocks &&
		Array.isArray( recreatedBlock.innerBlocks )
	) {
		recreatedBlock.innerBlocks = recreatedBlock.innerBlocks.map(
			( innerBlock ) =>
				recreateBlockWithProcessingState( innerBlock, skipProcessing )
		);
	}

	return recreatedBlock;
};

/**
 * Process the result of a site structure workflow update
 *
 * @param {Object} result - The result of the site structure workflow update
 */
async function processSiteStructureWorkflowResult( result ) {
	let sectionCount = 0;
	if ( isValidStoreSite() ) {
		sectionCount = result?.homepageSections?.length || 0;
	} else {
		sectionCount = result?.homepageSections?.length - 1 || 0;
	}

	// Insert dummy sections to prepare the canvas
	await insertDummySections( {
		count: sectionCount,
		replaceTemplateParts: true,
	} );
}

/**
 * Process the result of a compose layouts workflow update
 *
 * @param {Object}  options                 - The options for the compose layouts workflow result
 * @param {Object}  options.homepageLayouts - The homepage layouts from the workflow result
 * @param {Object}  options.pages           - The pages from the workflow result
 * @param {Object}  options.navigationMenu  - Optional existing navigation menu to use
 * @param {Object}  options.select          - Redux select functions
 * @param {Object}  options.dispatch        - Redux dispatch functions
 * @param {boolean} options.animate         - Whether to animate the patterns
 */
async function processComposeLayoutsWorkflowResult( {
	homepageLayouts,
	pages,
	navigationMenu: existingNavigationMenu = null,
	select,
	dispatch,
	animate = true,
} ) {
	// Process patterns through WordPress createBlock to add clientIds and validation properties
	const patterns = homepageLayouts[ 0 ].patterns;
	const patternsToAdd = patterns.map( ( patternData ) => {
		// Recreate all blocks using WordPress createBlock function
		const processedPattern = {
			...patternData,
			blocks: Array.isArray( patternData.blocks )
				? patternData.blocks.map( recreateBlockWithProcessingState )
				: [],
		};

		return {
			pattern: processedPattern,
			resolver: Promise.resolve( true ),
		};
	} );

	// Get site metadata
	const siteMeta = select.getSiteMetadata();
	const { siteTitle, siteDescription } = siteMeta;

	// Update site title and description
	const { editEntityRecord: editSiteEntity, saveEntityRecord } =
		window.wp.data.dispatch( coreStore );
	editSiteEntity( 'root', 'site', undefined, {
		title: siteTitle,
		description: siteDescription,
	} );

	// Create additional pages
	let navigationMenu = existingNavigationMenu;
	if ( pages?.length > 0 ) {
		log.info( '✅ Starting page creation for', pages.length, 'pages' );

		// Only create navigation menu if not passed
		if ( ! navigationMenu ) {
			navigationMenu = await saveEntityRecord(
				'postType',
				'wp_navigation',
				{
					title: 'Header Navigation',
					status: 'publish',
					content: serialize( [] ),
				}
			);

			// Set navigation menu ID in site metadata
			dispatch.setSiteMetadata(
				{ navigationId: navigationMenu.id },
				true
			);
		}

		await executeAbility( 'big-sky/add-pages', {
			pages,
			navigationMenuId: navigationMenu.id,
		} );
	}

	// Add patterns to canvas with animations
	await addPatternsToCanvas( patternsToAdd, {
		navigationMenu,
		animate,
	} );
}

/**
 * Process the result of a button variations workflow update
 *
 * @param {Object} buttonVariations - The button variations from the workflow result
 */
async function processButtonVariationsWorkflowResult( buttonVariations ) {
	try {
		await executeAbility( 'big-sky/set-styles', {
			button: buttonVariations[ 0 ]?.title,
			updateBlocks: false,
		} );
	} catch ( error ) {
		console.error(
			'❌ Error executing set-styles ability (button):',
			error
		);
		throw error;
	}
}

/**
 * Process the result of a color picker workflow update
 *
 * @param {Object} colorVariations - The color variations from the workflow result
 * @param {Object} dispatch        - The dispatch function
 */
async function processColorPickerWorkflowResult( colorVariations, dispatch ) {
	dispatch.pushGeneratedVariations( colorVariations );
	try {
		const colorTitle = colorVariations[ 0 ]?.title;
		if ( ! colorTitle ) {
			console.error( '❌ Color title is missing or undefined!' );
			throw new Error(
				'Color variation title is required but was not provided'
			);
		}

		await executeAbility( 'big-sky/set-styles', {
			color: colorTitle,
			updateBlocks: false,
		} );
	} catch ( error ) {
		console.error(
			'❌ Error executing set-styles ability (color):',
			error
		);
		throw error;
	}
}

/**
 * Process the result of a font picker workflow update
 *
 * @param {Object} fontThemeVariations   - The font theme variations from the workflow result
 * @param {Object} fontDynamicVariations - The font dynamic variations from the workflow result
 * @param {Object} dispatch              - The dispatch function
 */
async function processFontPickerWorkflowResult(
	fontThemeVariations,
	fontDynamicVariations,
	dispatch
) {
	dispatch.pushGeneratedVariations( fontDynamicVariations );

	// Load the font faces from dynamic variations as CSS in the editor
	if ( fontDynamicVariations?.length > 0 ) {
		const families = fontDynamicVariations.flatMap(
			( v ) => v.settings?.typography?.fontFamilies?.theme || []
		);
		if ( families.length > 0 ) {
			injectFontFamiliesIntoEditorIframe( families );
		}
	}

	try {
		const fontTitle =
			fontThemeVariations?.[ 0 ]?.title ||
			fontDynamicVariations?.[ 0 ]?.title ||
			'';
		await executeAbility( 'big-sky/set-styles', {
			font: fontTitle,
			updateBlocks: false,
		} );
	} catch ( error ) {
		console.error( '❌ Error executing set-styles ability (font):', error );
		throw error;
	}
}

/**
 * Get an Agents Manager ability, waiting up to `timeout` ms for it to register.
 *
 * Agents Manager registers its abilities in its own abilities store
 * (`core/abilities`), which `executeAbility()` doesn't read, and does so from
 * a lazy chunk once its chat loads.
 *
 * @param {string} name    The ability name.
 * @param {number} timeout How long to wait, in ms.
 * @return {Promise<Object|undefined>} The ability, or undefined if it never registered.
 */
async function getAgentsManagerAbility( name, timeout = 10000 ) {
	const getAbility = () =>
		window?.wp?.data?.select?.( 'core/abilities' )?.getAbility?.( name );
	const deadline = Date.now() + timeout;

	let ability = getAbility();
	while ( ! ability && Date.now() < deadline ) {
		await setDelay( 200 );
		ability = getAbility();
	}

	return ability;
}

/**
 * Process follow-up block edit results streamed from the workflow agent.
 *
 * @param {Object} result Parsed result payload from the workflow stream
 * @return {Promise<boolean>} Whether the update was processed as block edits
 */
async function processFollowUpBlockEdits( result ) {
	const followUpTasks = result.data.followUpTasks ?? false;
	const summary = result.data.summary || '';
	const reverseMap = { ...result.data.reverseMap };

	const blockEditorSelect = window?.wp?.data?.select?.( blockEditorStore );
	const { map: syntheticImageMap, imageClientIds } =
		buildSyntheticImageIdMap( blockEditorSelect );

	const missingSyntheticImageIds = new Set();
	const missingNonSyntheticIds = new Set();
	const usedImageClientIds = new Set();

	Object.entries( reverseMap ).forEach( ( [ key, mappedId ] ) => {
		if ( isSyntheticImageClientId( key ) ) {
			usedImageClientIds.add( mappedId );
		}
	} );

	const ensureMapping = ( clientId ) =>
		ensureReverseMapEntry(
			clientId,
			reverseMap,
			syntheticImageMap,
			missingNonSyntheticIds,
			missingSyntheticImageIds,
			imageClientIds,
			usedImageClientIds
		);

	const filteredUpdates = result.data.updates.filter( ( update ) =>
		ensureMapping( update?.clientId )
	);
	const filteredDeletes = result.data.deletes.filter( ( clientId ) =>
		ensureMapping( clientId )
	);

	// Ensure parents for inserts are mapped so they can be located when applying changes.
	for ( const insert of result.data.inserts ) {
		if ( insert?.parentClientId ) {
			ensureMapping( insert.parentClientId );
		}
	}

	if (
		missingSyntheticImageIds.size > 0 ||
		missingNonSyntheticIds.size > 0
	) {
		recordTracksEvent?.( 'big_sky_apply_block_edits_missing_client_ids', {
			missing_ids: Array.from( missingSyntheticImageIds ),
			non_synthetic_ids: Array.from( missingNonSyntheticIds ),
			source: 'workflow_followup',
		} );
	}

	if (
		! filteredUpdates.length &&
		! result.data.inserts.length &&
		! filteredDeletes.length
	) {
		return false;
	}

	try {
		const applyBlockEdits = await getAgentsManagerAbility(
			'big-sky/apply-block-edits'
		);

		if ( ! applyBlockEdits ) {
			throw new Error( 'Ability not found: big-sky/apply-block-edits' );
		}

		await applyBlockEdits.callback( {
			updates: filteredUpdates,
			inserts: result.data.inserts,
			deletes: filteredDeletes,
			summary,
			followUpTasks,
			reverseMap,
			suppressAssistantMessage: true,
		} );
	} catch ( error ) {
		console.error( '❌ Error executing apply-block-edits ability:', error );
		throw error;
	}
}

/**
 * Process pending page image generation after site build workflow completes.
 * Uses cached images from the workflow to populate images in newly created pages.
 *
 * @param {Object} select   - Redux select functions
 * @param {Object} dispatch - Redux dispatch functions
 */
async function processPendingPageImagesWrapper( select, dispatch ) {
	const pendingPages = select.getPendingPageImageProcessing();

	if ( ! pendingPages || pendingPages.length === 0 ) {
		return;
	}

	try {
		await processPendingPageImages( pendingPages );

		// Clear pending pages after processing
		dispatch.clearPendingPageImageProcessing();
	} catch ( error ) {
		console.error( '❌ Error processing pending page images:', error );
	}
}

/**
 * Cache images from workflow results for reuse.
 * Extracts image URLs from block updates and inserts, storing them in the cache
 * for later use in image generation.
 *
 * @param {Array}  updates  - Array of block updates from workflow
 * @param {Array}  inserts  - Array of block inserts from workflow
 * @param {Object} dispatch - Redux dispatch functions
 */
function cacheImagesFromWorkflow( updates, inserts, dispatch ) {
	const imageUpdates = [ ...updates, ...inserts ];

	imageUpdates.forEach( ( update ) => {
		if ( ! update?.attributes ) {
			return;
		}

		const { attributes, blockType } = update;
		let imageUrl = null;
		let imageAlt = null;
		let imageId = null;
		let isBackgroundImage = false;

		// Determine image type and extract data based on block type
		if ( blockType === 'core/image' ) {
			imageUrl = attributes.url;
			imageAlt = attributes.alt;
			imageId = attributes.id;
		} else if ( blockType === 'core/cover' ) {
			imageUrl = attributes.url;
			imageAlt = attributes.alt;
			imageId = attributes.id;
			isBackgroundImage = true;
		} else if ( blockType === 'core/site-logo' ) {
			imageUrl = attributes.url;
			imageAlt = attributes.alt;
			imageId = attributes.id;
		}

		// Cache the image if we found valid image data
		if ( imageUrl ) {
			const cacheKey = isBackgroundImage
				? imageCacheKeys.BACKGROUND_IMAGES
				: imageCacheKeys.IMAGES;

			const imageData = {
				url: imageUrl,
				alt: imageAlt || '',
				id: imageId,
				cached: Date.now(),
			};

			console.log(
				`💾 Caching ${
					isBackgroundImage ? 'background ' : ''
				}image from workflow:`,
				imageUrl
			);

			dispatch.addCachedImage( {
				cacheKey,
				imageData,
			} );
		}
	} );
}

/**
 * Extract category IDs from non-service products.
 *
 * @param {Array} products - Array of product data from workflow result.
 * @return {number[]} Array of unique category IDs.
 */
function getNonServiceCategoryIds( products ) {
	const categoryIds = [];
	for ( const product of products || [] ) {
		if ( product?.is_service ) {
			continue;
		}
		const categories = product?.categories;
		if ( ! Array.isArray( categories ) ) {
			continue;
		}
		for ( const category of categories ) {
			let categoryId = null;
			if ( category && typeof category === 'object' ) {
				categoryId =
					category.id !== null ? parseInt( category.id, 10 ) : null;
			}
			if ( categoryId !== null && ! Number.isNaN( categoryId ) ) {
				categoryIds.push( categoryId );
			}
		}
	}
	return [ ...new Set( categoryIds ) ];
}

/**
 * Extract service product IDs for single-product blocks.
 *
 * @param {Array} products - Array of product data from workflow result.
 * @return {number[]} Array of service product IDs.
 */
function getServiceProductIds( products ) {
	return ( products || [] )
		.filter( ( p ) => {
			if ( ! p?.is_service ) return false;
			const id = p.product_id ?? p.id;
			return id !== null;
		} )
		.map( ( p ) => parseInt( p.product_id ?? p.id, 10 ) )
		.filter( ( id ) => ! Number.isNaN( id ) );
}

/**
 * Remove big-sky processing classes from a className string.
 *
 * @param {string} [className] - Space-separated class names.
 * @return {string|undefined} Cleaned class names or undefined if empty.
 */
function removeProcessingClasses( className ) {
	if ( ! className || typeof className !== 'string' ) {
		return undefined;
	}
	const cleaned = className
		.split( ' ' )
		.filter(
			( cn ) =>
				! cn.startsWith( 'big-sky__is-processing' ) &&
				! cn.startsWith( 'big-sky__has-processed' )
		)
		.join( ' ' )
		.trim();
	return cleaned || undefined;
}

/**
 * Reconcile WooCommerce blocks with generated products:
 * - single-product: set productId from service products (cycling)
 * - product-collection: set query.taxQuery.product_cat to non-service categories
 *
 * @param {Array}    blocks                - Root blocks to process.
 * @param {number[]} serviceProductIds     - Service product IDs for single-product blocks.
 * @param {number[]} nonServiceCategoryIds - Non-service category IDs for product-collection blocks.
 */
function reconcileProductsInBlocks(
	blocks,
	serviceProductIds,
	nonServiceCategoryIds
) {
	const blockEditorSelect = window.wp.data?.select?.( blockEditorStore );
	const blockEditorDispatch = window.wp.data?.dispatch?.( blockEditorStore );
	let productIndex = 0;

	function walk( blockList ) {
		for ( const block of blockList || [] ) {
			if ( block?.name === 'woocommerce/single-product' ) {
				if ( serviceProductIds.length > 0 ) {
					const productId =
						serviceProductIds[
							productIndex % serviceProductIds.length
						];
					const clone = recreateBlock( {
						...block,
						attributes: {
							...block.attributes,
							productId,
							className: removeProcessingClasses(
								block.attributes?.className
							),
						},
					} );

					const parents =
						blockEditorSelect?.getBlockParents?.(
							block.clientId
						) ?? [];
					// Find the parent whose direct children include our block
					let parentClientId = null;
					for ( const pId of parents ) {
						const children =
							blockEditorSelect?.getBlocks?.( pId ) ?? [];
						if (
							children.some(
								( b ) => b.clientId === block.clientId
							)
						) {
							parentClientId = pId;
							break;
						}
					}

					if (
						parentClientId &&
						blockEditorDispatch?.replaceInnerBlocks
					) {
						const siblingBlocks =
							blockEditorSelect?.getBlocks?.( parentClientId ) ??
							[];
						const index = siblingBlocks.findIndex(
							( b ) => b.clientId === block.clientId
						);

						if ( index >= 0 ) {
							const newInnerBlocks = [
								...siblingBlocks.slice( 0, index ),
								clone,
								...siblingBlocks.slice( index + 1 ),
							];
							blockEditorDispatch.replaceInnerBlocks(
								parentClientId,
								newInnerBlocks,
								true
							);
						}
					} else {
						blockEditorDispatch?.replaceBlock?.(
							block.clientId,
							clone
						);
					}
					productIndex += 1;
				}
			}

			if ( block?.name === 'woocommerce/product-collection' ) {
				if ( nonServiceCategoryIds.length > 0 ) {
					const query = {
						...( block.attributes?.query || {} ),
						taxQuery: {
							...( block.attributes?.query?.taxQuery || {} ),
							product_cat: nonServiceCategoryIds,
						},
					};
					const cleanedClassName =
						removeProcessingClasses(
							block.attributes?.className
						) ??
						block.attributes?.className ??
						'';
					blockEditorDispatch?.updateBlockAttributes?.(
						block.clientId,
						{
							query,
							className: cleanedClassName,
						}
					);
				}
			}

			if ( block?.innerBlocks?.length ) {
				walk( block.innerBlocks );
			}
		}
	}

	walk( blocks );
}

async function processProductsWorkflowResult( result ) {
	const products = result?.products || [];
	const rootBlocks = getRootBlocksOfContent();
	const serviceProductIds = getServiceProductIds( products );
	const nonServiceCategoryIds = getNonServiceCategoryIds( products );

	reconcileProductsInBlocks(
		rootBlocks,
		serviceProductIds,
		nonServiceCategoryIds
	);
}

/**
 * Show a thinking message during site build. Uses the given message if provided,
 * otherwise picks a random message.
 *
 * @param {Object} dispatch  - Redux dispatch functions
 * @param {string} [message] - Optional specific message to show
 */
function showThinkingMessage( dispatch, message = null ) {
	if ( message ) {
		dispatch.setThinkingMessage( message );
		return;
	}

	const messages = [
		__( 'Cooking up something good…', 'big-sky' ),
		__( 'Making progress…', 'big-sky' ),
		__( 'Putting the pieces together…', 'big-sky' ),
		__( 'Almost there…', 'big-sky' ),
		__( 'Fine-tuning things…', 'big-sky' ),
	];

	const randomMessage =
		// eslint-disable-next-line no-restricted-syntax -- Not generating IDs, just picking a random message
		messages[ Math.floor( Math.random() * messages.length ) ];
	dispatch.setThinkingMessage( randomMessage );
}

/**
 * Process the result of a workflow update
 *
 * @param {string} toolId   - The ID of the tool that called the workflow
 * @param {Object} result   - The result of a workflow update
 * @param {Object} select   - Redux select functions
 * @param {Object} dispatch - Redux dispatch functions
 */
async function processResult( toolId, result, select, dispatch ) {
	switch ( toolId ) {
		case 'prepare_site':
			return false;
		case 'get_site_structure':
			await processSiteStructureWorkflowResult(
				result,
				select,
				dispatch
			);
			await setDelay( 500 );
			dispatch.setHeaderSectionIsReady( true );
			dispatch.assistantSay( __( 'Planned your site', 'big-sky' ), {
				context: 'site-build-completed',
			} );
			showThinkingMessage( dispatch );
			return false;
		case 'compose_layouts':
		case 'big-sky/compose-site-layouts':
			// handle the streamlined workflow
			if ( result?.data?.promises?.length > 0 ) {
				return false;
			}

			// if there are no layouts, throw an error
			if ( result?.composedLayouts?.homepage?.layouts.length === 0 ) {
				throw new Error( __( 'No layouts were created', 'big-sky' ) );
			}

			showThinkingMessage( dispatch );
			await processComposeLayoutsWorkflowResult( {
				homepageLayouts: result.composedLayouts.homepage.layouts,
				pages: result?.composedLayouts?.pages,
				select,
				dispatch,
			} );
			dispatch.assistantSay(
				__( 'Created initial layout and pages', 'big-sky' ),
				{
					context: 'site-build-completed',
				}
			);
			return false;
		case 'process_images':
			// Retrieve the navigation menu from site metadata
			const siteMeta = select.getSiteMetadata();
			const navigationId = siteMeta?.navigationId;
			let navigationMenu = null;

			if ( navigationId ) {
				const { select: coreSelect } = window.wp.data;
				navigationMenu = coreSelect( coreStore ).getEntityRecord(
					'postType',
					'wp_navigation',
					navigationId
				);
			}

			await processComposeLayoutsWorkflowResult( {
				homepageLayouts:
					result?.processed_structure?.composedLayouts?.homepage
						?.layouts,
				pages: [],
				navigationMenu,
				select,
				dispatch,
				animate: false,
			} );
			dispatch.assistantSay( __( 'Applied images', 'big-sky' ), {
				context: 'site-build-completed',
			} );
			return false;
		case 'get_button_variations':
		case 'big-sky/generate-button-variations':
			// handle the streamlined workflow
			if ( result?.data?.promises?.length > 0 ) {
				return false;
			}

			if ( result?.data?.props?.buttonVariations?.length > 0 ) {
				showThinkingMessage( dispatch );
				await processButtonVariationsWorkflowResult(
					result.data.props.buttonVariations,
					dispatch
				);
				dispatch.assistantSay(
					__( 'Applied button styles', 'big-sky' ),
					{
						context: 'site-build-completed',
					}
				);
			}
			return false;
		case 'get_color_variations':
		case 'big-sky/color-palette':
			// handle the streamlined workflow
			if ( result?.data?.promises?.length > 0 ) {
				return false;
			}

			if ( result?.data?.props?.variations?.length > 0 ) {
				showThinkingMessage( dispatch );
				await processColorPickerWorkflowResult(
					result?.data?.props?.variations,
					dispatch
				);
				dispatch.assistantSay( __( 'Applied color theme', 'big-sky' ), {
					context: 'site-build-completed',
				} );
			}
			return false;
		case 'get_font_variations':
		case 'big-sky/font-picker':
			// handle the streamlined workflow
			if ( result?.data?.promises?.length > 0 ) {
				return false;
			}

			if (
				result?.data?.props?.themeVariations?.length > 0 ||
				result?.data?.props?.dynamicVariations?.length > 0
			) {
				showThinkingMessage( dispatch );
				await processFontPickerWorkflowResult(
					result?.data?.props?.themeVariations,
					result?.data?.props?.dynamicVariations,
					dispatch
				);
				dispatch.assistantSay( __( 'Applied fonts', 'big-sky' ), {
					context: 'site-build-completed',
				} );
			}
			return false;
		case 'wpcom/generate-image':
		case 'big-sky/generate-image':
			showThinkingMessage( dispatch );

			// Handle block edits (updates, inserts, deletes)
			const updates = ( result?.data?.updates || [] ).filter( Boolean );
			const inserts = ( result?.data?.inserts || [] ).filter( Boolean );
			const deletes = ( result?.data?.deletes || [] ).filter( Boolean );

			// Cache images from the workflow for reuse
			cacheImagesFromWorkflow( updates, inserts, dispatch );

			if ( updates.length || inserts.length || deletes.length ) {
				result.data.updates = updates;
				result.data.inserts = inserts;
				result.data.deletes = deletes;
				await processFollowUpBlockEdits( result );
				return true;
			}
			return true;
		default:
			return false;
	}
}

/**
 * Store action to send a streaming message to a workflow agent
 * This provides a way to execute workflows from anywhere in the app without hooks
 * Handles the complete conversation flow internally - adds messages to store, manages thinking state, etc.
 *
 * @param {string}  message                 - The message to send to the workflow
 * @param {Object}  options                 - Optional parameters for the workflow
 * @param {boolean} options.withHistory     - Whether to include conversation history (default: false)
 * @param {string}  options.agentKey        - Key to identify the agent instance (default: 'workflow-agent')
 * @param {string}  options.sessionId       - Session ID for the conversation (default: 'default-session')
 * @param {string}  options.workflowSlug    - Slug of the workflow to execute (default: 'wpcom-workflow-site-builder')
 * @param {string}  options.workflowVersion - Version of the workflow (default: '1.0.0')
 * @param {string}  options.workflowYaml    - Inline YAML configuration (optional, overrides slug/version)
 * @param {number}  options.userId          - User ID for the workflow context
 * @param {number}  options.blogId          - Blog ID for the workflow context
 * @return {Function} Async thunk action that returns a promise
 */
export const runSiteBuildAgent =
	( message, options = {} ) =>
	async ( { select, dispatch } ) => {
		const {
			withHistory = false,
			agentKey = 'workflow-agent',
			sessionId = select.getSessionId(),
			...otherOptions
		} = options;

		const siteId =
			window?.JP_CONNECTION_INITIAL_STATE?.userConnectionData?.currentUser
				?.blogId || '';

		const messages = select.getMessages();

		let agentQuickActionMessage;

		// If there is only one message in the store and it is from the assistant
		// it must be a quick action message so we need to include it in the call
		// to the agent.
		if (
			messages.length === 1 &&
			messages[ 0 ]?.role === messageRoles.ASSISTANT &&
			messages[ 0 ]?.content[ 0 ]?.type === 'text'
		) {
			agentQuickActionMessage = messages[ 0 ]?.content[ 0 ]?.text;
		}

		const agentManager = getAgentManager();

		// Ensure agent exists (create if needed)
		if ( ! agentManager.hasAgent( agentKey ) ) {
			// Clear any stored conversation history. We have stopped storing
			// locally for now as this was causing issues with the agent.
			window?.sessionStorage.removeItem(
				`a8c_agenttic_conversation_history_${ agentKey }-${ siteId }`
			);

			// WORKAROUND: Pass site_metadata as constructorArguments via clientContext.
			// The agenttic-client doesn't support top-level constructor_arguments in JSON-RPC requests,
			// so we pass them inside clientContext. The backend extracts clientContext.constructorArguments
			// and merges them with constructor_arguments before creating the agent.
			// TODO: Remove this workaround once agenttic-client supports constructor_arguments natively.
			// This ensures Jetpack sites have fresh metadata without waiting for shadow site sync.
			const contextProvider = {
				getClientContext: () => {
					const siteMetadata = select.getSiteMetadata();
					log.info(
						'📋 Sending site_metadata via constructorArguments:',
						siteMetadata
					);
					return {
						constructorArguments: {
							site_metadata: siteMetadata,
						},
					};
				},
			};
			const toolProvider = () => ( {} );

			log.info( '🏗️ Creating workflow agent with config:', {
				agentId: 'site-builder-workflow',
				agentUrl: 'https://public-api.wordpress.com/wpcom/v2/ai/agent',
				sessionId,
				conversationStorageKey: `${ agentKey }-${ siteId }`,
			} );

			await agentManager.createAgent( agentKey, {
				agentId: 'site-builder-workflow',
				agentUrl: 'https://public-api.wordpress.com/wpcom/v2/ai/agent',
				sessionId,
				conversationStorageKey: `${ agentKey }-${ siteId }`,
				contextProvider,
				toolProvider,
				authProvider: async () => {
					log.info(
						'🔐 Requesting Jetpack token for workflow agent'
					);
					const jetpackToken = await requestJetpackToken();
					log.info(
						'🔑 Jetpack token received:',
						!! jetpackToken.token
					);
					return {
						Authorization: `Bearer ${ jetpackToken.token }`,
					};
				},
			} );

			log.info( '✅ Workflow agent created successfully' );
		}

		// Set thinking state and add thinking message
		dispatch.setThinking( true );

		const messageToSend = agentQuickActionMessage
			? `Agent question: ${ agentQuickActionMessage } \n\n User reply: ${ message }`
			: message;

		// Send message and stream response
		log.info( '🔄 Sending message to workflow agent (streaming)' );
		log.info( '📤 Sending message:', messageToSend );
		log.info( '⚙️ Message options:', {
			withHistory,
			sessionId,
			...otherOptions,
		} );
		const aiStep = 'edit';
		dispatch.setAiStep( aiStep );
		const url = new URL( window.location.href );
		url.searchParams.set( 'ai-step', aiStep );
		window.history.pushState( {}, '', url );

		// Use the global agents manager action to ensure the chat UI is opened
		window.__agentsManagerActions?.setChatOpen( true );

		let products = null;
		for await ( const update of agentManager.sendMessageStream(
			agentKey,
			'Build the site',
			{
				withHistory: false,
				sessionId,
				...otherOptions,
			}
		) ) {
			log.info( '📨 Received workflow update:', update );

			if ( ! update?.status?.message?.parts ) {
				continue;
			}

			for ( const part of update.status.message.parts ) {
				if ( part.type !== 'data' || ! part.data?.result ) {
					continue;
				}

				const toolId = part.data.toolId;
				// store products so we can update the blocks later
				if ( toolId === 'execute_promises' ) {
					products = part.data.result?.products ?? null;
				}
				await processResult(
					toolId,
					part.data.result,
					select,
					dispatch
				);
			}
		}

		if ( products?.length > 0 ) {
			showThinkingMessage( dispatch );
			await processProductsWorkflowResult( {
				products,
			} );
			dispatch.assistantSay(
				__( 'Activated marketing features', 'big-sky' ),
				{
					context: 'site-build-completed',
				}
			);
		}

		// Process pending page images now that workflow is complete and images are cached
		await processPendingPageImagesWrapper( select, dispatch );

		dispatch.assistantSay( __( 'Site build complete', 'big-sky' ), {
			context: 'site-build-completed',
		} );

		recordTracksEvent( 'building_site_finished' );
		// Reset the block processing states
		resetAllBlockProcessingStates();

		dispatch.setThinking( false );
		dispatch.setThinkingMessage( null );
		dispatch.setIsBuildingSite( false );

		// No `site-build-completed` context, so it shows outside the progress
		// card, with Agents Manager's design suggestions under it.
		dispatch.assistantSay(
			__(
				'Your site is ready! What would you like to do next?',
				'big-sky'
			),
			{ hasEditorEmptyViewSuggestions: true }
		);
	};
