/** WordPress dependencies */
import { store as coreStore } from '@wordpress/core-data';
import { useDispatch, useSelect } from '@wordpress/data';
import { useCallback } from '@wordpress/element';

/**
 * Saves all dirty entity records.
 *
 * @return {Function} Function that when called, saves everything.
 */
export default function useSaveEverything() {
	const { saveEditedEntityRecord } = useDispatch( coreStore );
	const { __experimentalGetDirtyEntityRecords } = useSelect(
		( select ) => select( coreStore ),
		[]
	);
	return useCallback( async () => {
		const dirtyEntityRecords = __experimentalGetDirtyEntityRecords();
		for ( const { kind, name, key } of dirtyEntityRecords ) {
			await saveEditedEntityRecord( kind, name, key );
		}
	}, [ __experimentalGetDirtyEntityRecords, saveEditedEntityRecord ] );
}
